window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[359]={"id":"359","numero":359,"titre":"Détresse et insuffisance respiratoire aiguë","objectifs":[{"id":"359-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la détresse et de l’insuffisance respiratoire aiguë","contenu":"<p>Deux notions à <span class=\"kw-ci\">ne jamais</span> confondre : la <strong><span class=\"kw-def\">détresse respiratoire aiguë (DRA)</span></strong> est une définition <strong>clinique</strong>, l'<strong><span class=\"kw-def\">insuffisance respiratoire aiguë (IRA)</span></strong> une définition <strong>gazométrique</strong>.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Détresse respiratoire aiguë</span></strong><br>définition <strong>clinique</strong></td>\n            <td>Ensemble de <span class=\"kw-clinique\">signes cliniques respiratoires</span> témoignant de la gravité d'une affection respiratoire. Traduit l'<strong>inadéquation</strong> entre <span class=\"kw-clinique\">les</span> charges imposées à l'appareil respiratoire et ses capacités à y faire face. Peut annoncer un <span class=\"kw-alerte\">arrêt cardio-respiratoire par hypoxie</span>.<br>Regroupe : conséquences directes de l'atteinte (<span class=\"kw-clinique\">cyanose</span>) ; mécanismes compensateurs (recrutement des <span class=\"kw-clinique\">muscles respiratoires accessoires</span>). N'inclut pas le retentissement hémodynamique ou neurologique associé.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Insuffisance respiratoire aiguë</span></strong><br>définition <strong>gazométrique</strong></td>\n            <td>Altération aiguë de l'hématose :<br><strong><span class=\"kw-def\">IRA</span> type 1</strong> (hypoxémique) : <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&lt; 60 mmHg</span>, sans hypercapnie ;<br><strong><span class=\"kw-def\">IRA</span> type 2</strong> (hypercapnique) : <span class=\"kw-bio\">PaCO2</span> <span class=\"kw-chiffre\">&gt; 45 mmHg</span>, peut rapidement se compliquer d'une <span class=\"kw-alerte\">acidose</span> respiratoire (= insuffisance ventilatoire aiguë lorsqu'il n'y a pas d'hypoxémie associée).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> L'<span class=\"kw-alerte\">hypoxie tissulaire sans hypoxémie</span> n'entre PAS dans la définition de l'<span class=\"kw-def\">IRA</span> : altération du <strong>transport de l'O2</strong> (<span class=\"kw-etio\">anémie</span>, <span class=\"kw-etio\">intoxication au CO</span>, <span class=\"kw-etio\">état de choc</span>) ou de la <strong>respiration cellulaire</strong> (<span class=\"kw-etio\">intoxication au cyanure</span>, <span class=\"kw-etio\">sepsis grave</span>).</div>\n      <p>La DRA peut <strong>précéder</strong> une authentique <span class=\"kw-def\">IRA</span> gazométrique : une <span class=\"kw-bio\">hypocapnie</span> associée à une <span class=\"kw-bio\">PaO2</span> normale témoigne souvent d'une hypoxémie profonde masquée par l'hyperventilation alvéolaire. <span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">gaz du sang</span> peuvent donc être <span class=\"kw-alerte\">faussement rassurants</span> — savoir les renouveler précocement.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"359-2","rang":"A","rubrique":"Définition","titre":"Connaître les critères de diagnostic, les variations avec l’âge","contenu":"<p>Le diagnostic de <span class=\"kw-def\">détresse respiratoire aiguë</span> est <strong>clinique</strong> : il peut se faire <strong>exclusivement à l'inspection</strong>, sans stéthoscope ni examen complémentaire. <strong>Un seul signe suffit</strong> à poser le diagnostic.</p>\n      <p>Le caractère pathologique des signes respiratoires s'apprécie en fonction de l'<strong>âge</strong> : la <span class=\"kw-clinique\">fréquence respiratoire</span> et la <span class=\"kw-clinique\">fréquence cardiaque</span> normales varient fortement chez l'enfant (elles sont aussi influencées par la <span class=\"kw-clinique\">fièvre</span>, l'agitation, l'anxiété).</p>\n      <table >\n        <thead><tr><th>Âge</th><th>FR normale (/min)</th><th>FC normale (/min)</th><th>PAS — limite basse (mmHg)</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Nouveau-né</strong> (&lt;<span class=\"kw-chiffre\"> 1 mois</span>)</td><td><span class=\"kw-chiffre\">35-60</span></td><td><span class=\"kw-chiffre\">135 ± 35</span></td><td><span class=\"kw-chiffre\">60</span> (&lt; 1 sem.) à <span class=\"kw-chiffre\">65</span> (&lt;<span class=\"kw-chiffre\"> 1 mois</span>)</td></tr>\n          <tr><td><strong>Nourrisson</strong> (<span class=\"kw-chiffre\">1-12 mois</span>)</td><td><span class=\"kw-chiffre\">30-50</span></td><td><span class=\"kw-chiffre\">120 ± 35</span></td><td><span class=\"kw-chiffre\">70</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">1-2 ans</span></strong></td><td><span class=\"kw-chiffre\">20-40</span></td><td><span class=\"kw-chiffre\">110 ± 30</span></td><td><span class=\"kw-chiffre\">70 + 2 × âge</span> (<span class=\"kw-chiffre\">1-10 ans</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">2-4 ans</span></strong></td><td><span class=\"kw-chiffre\">20-35</span></td><td><span class=\"kw-chiffre\">100 ± 30</span></td><td><span class=\"kw-chiffre\">70 + 2 × âge</span> (années)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">5-10 ans</span></strong></td><td><span class=\"kw-chiffre\">20-35</span></td><td><span class=\"kw-chiffre\">90 ± 35</span></td><td><span class=\"kw-chiffre\">70 + 2 × âge</span> (années)</td></tr>\n          <tr><td><strong>Adolescent</strong> (&gt;<span class=\"kw-chiffre\"> 10 ans</span>)</td><td><span class=\"kw-chiffre\">12-20</span></td><td><span class=\"kw-chiffre\">85 ± 25</span></td><td><span class=\"kw-chiffre\">90</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Chez l'adulte, la <strong><span class=\"kw-clinique\">tachypnée</span></strong> se définit par une <span class=\"kw-clinique\">FR</span> <span class=\"kw-chiffre\">≥ 25/min</span> ; la <strong><span class=\"kw-clinique\">polypnée</span> / <span class=\"kw-clinique\">tachypnée</span></strong> par une <span class=\"kw-clinique\">FR</span> <span class=\"kw-chiffre\">&gt; 16/min</span>. La <span class=\"kw-clinique\">polypnée superficielle</span> associe accélération de la FR et diminution du volume courant.</div>","frequence":2},{"id":"359-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principes physiopathologiques de l’hypoxémie","contenu":"<p><span class=\"kw-clinique\">Les</span> mécanismes de l'<span class=\"kw-def\">hypoxémie</span> aiguë sont les mêmes que ceux de l'hypoxémie chronique de l'<span class=\"kw-def\">IRC</span>. Plusieurs peuvent être <strong>intriqués</strong> chez un même patient.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Principe</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Effet shunt</strong></td><td>Zones perfusées mais <strong>mal ventilées</strong> (comblement alvéolaire : <span class=\"kw-etio\">pneumonie</span>, <span class=\"kw-etio\">œdème</span>). Hypoxémie partiellement corrigée par l'O2.</td></tr>\n          <tr><td><strong>Shunt vrai</strong> (anatomique)</td><td>Sang veineux rejoignant le sang artériel <strong>sans passer</strong> par une zone ventilée : <span class=\"kw-etio\">shunt droit-gauche</span> à travers un <span class=\"kw-etio\">foramen ovale perméable</span>. Hypoxémie <span class=\"kw-alerte\">non corrigée</span> par l'O2.</td></tr>\n          <tr><td><strong>Effet espace mort</strong></td><td>Zones <strong>ventilées mais mal perfusées</strong> : typique de l'<span class=\"kw-etio\">embolie pulmonaire</span> (hypoxémie souvent modérée, par redistribution du débit cardiaque vers <span class=\"kw-clinique\">les</span> zones perfusées → effet shunt secondaire).</td></tr>\n          <tr><td><strong>Hypoventilation alvéolaire</strong></td><td>Diminution du volume courant ou de la FR, ou augmentation de l'espace mort : associe <span class=\"kw-bio\">hypoxémie</span> + <span class=\"kw-bio\">hypercapnie</span>.</td></tr>\n        </tbody>\n      </table>\n      <h4>Effet « basse PvO2 »</h4>\n      <p>Situation très fréquente en <span class=\"kw-alerte\">réanimation</span>. En cas de <strong>shunt</strong>, la saturation veineuse en O2 (<span class=\"kw-bio\">SvO2</span>) influence la saturation artérielle : plus la <span class=\"kw-bio\">SvO2</span> est basse, plus la <span class=\"kw-bio\">SaO2</span> est basse.</p>\n      <ul>\n        <li>Un <span class=\"kw-etio\">état de choc</span> avec <strong>débit cardiaque insuffisant</strong> diminue le transport artériel en O2.</li>\n        <li><span class=\"kw-clinique\">Les</span> organes compensent en <strong>augmentant l'extraction périphérique d'O2</strong> (EO2) → la <span class=\"kw-bio\">SvO2</span> chute.</li>\n        <li>En présence d'un shunt, ce sang veineux désaturé <strong>contamine</strong> le sang artériel et génère / aggrave l'hypoxémie : c'est l'effet « basse PvO2 ».</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>CAT.</strong> En cas d'effet « basse PvO2 », c'est la <strong>correction du <span class=\"kw-alerte\">choc</span></strong> qui améliore l'oxygénation.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":4},{"id":"359-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les anomalies de la pompe ventilatoire","contenu":"<p>La <span class=\"kw-def\">pompe ventilatoire</span> = l'ensemble des muscles qui assurent la ventilation. En <span class=\"kw-alerte\">détresse</span>, on observe d'abord des <strong>signes de lutte</strong> (recrutement musculaire), puis des <strong>signes de faillite</strong> (épuisement).</p>\n      <table >\n        <thead><tr><th>Groupe</th><th>Anomalies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Muscles inspiratoires accessoires</strong></td>\n            <td><span class=\"kw-clinique\">Scalènes</span>, <span class=\"kw-clinique\">intercostaux externes</span>, <span class=\"kw-clinique\">sterno-cléido-mastoïdiens</span> : leur recrutement (<span class=\"kw-alerte\">tirage</span>) doit faire craindre une <span class=\"kw-alerte\">faillite ventilatoire</span> — contrairement au diaphragme, ils ne peuvent pas se contracter de façon soutenue.<br>Signes : <span class=\"kw-clinique\">tirage</span> sus-claviculaire, sus-sternal, intercostal ; <span class=\"kw-clinique\">pouls respiratoire</span> ; <span class=\"kw-clinique\">signe de Campbell</span> (descente du cartilage thyroïde à l'inspiration).</td>\n          </tr>\n          <tr>\n            <td><strong>Muscles expiratoires</strong></td>\n            <td><span class=\"kw-clinique\">Expiration abdominale active</span> : recrutement des muscles abdominaux à l'expiration → oriente vers une <span class=\"kw-etio\">pathologie obstructive</span> (ex. <span class=\"kw-def\">BPCO</span>). Permet de descendre sous la CRF. Autre signe : <span class=\"kw-clinique\">respiration lèvres pincées</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Faillite de la pompe</strong></td>\n            <td><span class=\"kw-alerte\">Respiration abdominale paradoxale</span> : recul de la paroi abdominale à l'inspiration (au lieu de l'expansion attendue) → traduit la <strong>fatigue du diaphragme</strong>. Accompagnée d'<span class=\"kw-clinique\">orthopnée</span> (<span class=\"kw-ci\">décubitus dorsal contre-indiqué</span>). Le <span class=\"kw-clinique\">balancement thoraco-abdominal</span> associe respiration paradoxale + expiration active.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Plus la <span class=\"kw-clinique\">polypnée est superficielle</span>, plus elle entraîne une <span class=\"kw-alerte\">hypoventilation alvéolaire</span> par augmentation de l'espace mort. La respiration paradoxale fait craindre une <span class=\"kw-alerte\">défaillance</span> à court terme et doit faire discuter une <strong>assistance ventilatoire</strong>.</div>","frequence":0},{"id":"359-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les éléments physiopathologiques du syndrome de détresse respiratoire aiguë (SDRA) et les causes principales, maladie des membranes hyalines du nouveau-né","contenu":"<p>Le <strong><span class=\"kw-def\">SDRA</span></strong> repose sur des <strong>lésions pulmonaires bilatérales aiguës</strong> non dues à une cause cardiogénique. C'est un <span class=\"kw-def\">œdème pulmonaire lésionnel</span> — à opposer à l'<span class=\"kw-def\">OAP</span> hémodynamique.</p>\n      <h4>Définition de Berlin — 4 critères</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Détresse</span> respiratoire d'<span class=\"kw-clinique\">évolution</span> aiguë (<span class=\"kw-chiffre\">&lt; 7 jours</span> après un facteur déclenchant) ;</li>\n        <li><span class=\"kw-imagerie\">Opacités alvéolaires bilatérales diffuses</span> radiographiques, non expliquées par un épanchement, une atélectasie ou des nodules ;</li>\n        <li>Hypoxémie avec rapport <span class=\"kw-bio\">PaO2/FiO2</span> <span class=\"kw-chiffre\">&lt; 300</span> ;</li>\n        <li><span class=\"kw-alerte\">Détresse</span> non entièrement expliquée par une <span class=\"kw-def\">insuffisance cardiaque</span> ou un remplissage excessif (<span class=\"kw-bio\">Pcap / PAPO</span> <span class=\"kw-chiffre\">&lt; 15 mmHg</span>).</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th><span class=\"kw-bio\">PaO2</span>/FiO2</th><th>Condition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">SDRA</span> léger</strong></td><td><span class=\"kw-chiffre\">200-300 mmHg</span></td><td rowspan=\"3\">Sous <span class=\"kw-ttt\">ventilation mécanique</span> avec <span class=\"kw-chiffre\">PEP / CPAP ≥ 5 cmH2O</span></td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">SDRA</span> modéré</strong></td><td><span class=\"kw-chiffre\">100-200 mmHg</span></td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">SDRA</span> sévère</strong></td><td><span class=\"kw-chiffre\">≤ 100 mmHg</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mécanisme.</strong> Le <span class=\"kw-alerte\">SDRA</span> est lésionnel : <span class=\"kw-alerte\">altération directe de la membrane alvéolo-capillaire</span> → exsudat à forte teneur en protides, <span class=\"kw-bio\">pression capillaire normale ou basse</span> (<span class=\"kw-chiffre\">&lt; 18 mmHg</span>). L'<span class=\"kw-def\">OAP</span> hémodynamique, lui, résulte d'une ↑ pression hydrostatique ou d'une ↓ pression oncotique. Conséquences communes : <span class=\"kw-alerte\">shunt vrai fonctionnel</span> + diminution de la <strong>compliance pulmonaire</strong>.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/359/rxt-sdra-opacites-alveolaires-bilaterales.png\" alt=\"Radiographie thoracique de face : opacités alvéolaires bilatérales diffuses, pattern de syndrome de détresse respiratoire aiguë\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\"><span class=\"kw-imagerie\">Radiographie</span> thoracique</span> d'un <span class=\"kw-alerte\">SDRA</span> : <span class=\"kw-imagerie\">opacités alvéolaires bilatérales diffuses</span>, non expliquées par un épanchement, une atélectasie ou des nodules (<span class=\"kw-def\">critère de</span> Berlin). Source : fiche source EDN item 359.</figcaption>\n      </figure>\n      <h4>Causes principales du <span class=\"kw-alerte\">SDRA</span></h4>\n      <table >\n        <thead><tr><th>Agression exogène (épithéliale)</th><th>Agression endogène (endothéliale)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Contusion pulmonaire</span><br><span class=\"kw-etio\">Pneumonie virale</span> (varicelle, COVID-19, <span class=\"kw-etio\">grippe</span> maligne), <span class=\"kw-etio\">bactérienne</span> ou <span class=\"kw-etio\">fongique</span> (pneumocystose)<br>Agression <span class=\"kw-etio\">toxique</span> : <span class=\"kw-etio\">inhalation de fumées</span> ; <span class=\"kw-etio\">inhalation de liquide gastrique</span> (<span class=\"kw-clinique\">syndrome de Mendelson</span>) ; <span class=\"kw-etio\">noyade</span></td>\n            <td>Toute pathologie avec <span class=\"kw-def\">syndrome inflammatoire</span> systémique :<br><span class=\"kw-etio\">sepsis sévère</span> ; <span class=\"kw-etio\">pancréatite aiguë</span> ; <span class=\"kw-etio\">embolie amniotique</span> ; <span class=\"kw-etio\">circulation extra-corporelle</span> ; <span class=\"kw-etio\">transfusions massives (TRALI)</span> ; <span class=\"kw-etio\">polytraumatismes</span> ; <span class=\"kw-etio\">brûlures étendues</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La <strong>maladie des membranes hyalines du nouveau-né</strong> (déficit en surfactant du prématuré) n'est pas traitée dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>359-detresse-insuffisance-respiratoire-aigue/</code>. Kevin enrichira ce point depuis le Collège de Pédiatrie / item 359 néonatal.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 358 — <span class=\"kw-def\">Pancréatite aiguë</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span></em></p>","frequence":0},{"id":"359-6","rang":"A","rubrique":"Identifier une urgence","titre":"Reconnaître les signes de gravité cliniques et gazométriques","contenu":"<p>Objectif central et très tombé. <span class=\"kw-clinique\">Les</span> signes se hiérarchisent en <strong>signes de lutte</strong> (compensation), <strong>signes de faillite</strong> (<span class=\"kw-alerte\">décompensation</span>), <strong>signes circulatoires</strong>, et critères <strong>gazométriques</strong>.</p>\n      <h4>Signes de lutte</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Tachypnée</span> (<span class=\"kw-chiffre\">FR ≥ 25/min</span> chez l'adulte), <span class=\"kw-clinique\">polypnée superficielle</span> ;</li>\n        <li>Signes de <span class=\"kw-ttt\">réduction</span> du volume courant : <span class=\"kw-clinique\">hypophonie</span> (difficulté à parler), <span class=\"kw-clinique\">inefficacité de la toux</span> ;</li>\n        <li><span class=\"kw-clinique\">Tirages</span> (recrutement des muscles accessoires) ; <span class=\"kw-clinique\">expiration abdominale active</span> (oriente vers une obstruction) ;</li>\n        <li><span class=\"kw-clinique\">Battement des ailes du nez</span> — surtout chez le très petit enfant.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> La <span class=\"kw-alerte\">bradypnée</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">irrégularités respiratoires</span> ne sont PAS des signes respiratoires : elles traduisent une <strong><span class=\"kw-alerte\">défaillance</span> neurologique</strong> (extrême gravité, <span class=\"kw-def\">annonce</span> un arrêt respiratoire) ou un <strong>épuisement</strong> du système respiratoire.</div>\n      <h4>Signes de faillite</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Respiration abdominale paradoxale</span> : faillite de la pompe ventilatoire, avec <span class=\"kw-clinique\">orthopnée</span> (<span class=\"kw-ci\">décubitus dorsal contre-indiqué</span>) ;</li>\n        <li><span class=\"kw-alerte\">Cyanose</span> : <span class=\"kw-bio\">Hb désoxygénée &gt; 5 g/dL</span>, témoigne d'une hypoxémie profonde (<span class=\"kw-bio\">SaO2 ≤ 85 %</span>). Absente / tardive si <span class=\"kw-etio\">anémie profonde</span> ; regarder la couleur de la <strong>langue chez <span class=\"kw-clinique\">les</span> mélanodermes</strong>. Impose une <span class=\"kw-ttt\">oxygénothérapie</span> immédiate ;</li>\n        <li>Retentissement neurologique : <span class=\"kw-clinique\">astérixis</span> (<span class=\"kw-clinique\">flapping</span>, très évocateur d'<span class=\"kw-alerte\">hypercapnie</span>) ; troubles du comportement / vigilance (hypercapnie et/ou hypoxie cérébrale). Un <span class=\"kw-alerte\">Glasgow ≤ 8</span> impose l'<span class=\"kw-ttt\">intubation</span>.</li>\n      </ul>\n      <h4>Signes circulatoires (4 à rechercher systématiquement)</h4>\n      <table >\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cœur pulmonaire aigu</strong></td><td><span class=\"kw-clinique\">Turgescence jugulaire</span>, <span class=\"kw-clinique\">reflux hépato-jugulaire</span>, <span class=\"kw-clinique\">hépatomégalie douloureuse</span>, signe de Harzer. Causes : <span class=\"kw-etio\">EP massive</span>, <span class=\"kw-etio\">PNO compressif</span>, <span class=\"kw-etio\">asthme aigu grave</span>, <span class=\"kw-etio\">tamponnade</span>.</td></tr>\n          <tr><td><strong>Pouls paradoxal</strong></td><td>Diminution de la <span class=\"kw-bio\">PAS</span> à l'inspiration de <span class=\"kw-chiffre\">&gt; 10 mmHg</span>. Causes : <span class=\"kw-etio\">tamponnade</span>, <span class=\"kw-etio\">asthme aigu grave</span>.</td></tr>\n          <tr><td><strong>Signes d'hypercapnie</strong> extra-neurologiques</td><td>Réponse adrénergique : <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">tremblements</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">HTA</span>. Effet vasodilatateur du CO2 : <span class=\"kw-clinique\">céphalées</span>, hypervascularisation des conjonctives.</td></tr>\n          <tr><td><strong>État de <span class=\"kw-alerte\">choc</span></strong></td><td>Recherche d'un retentissement hémodynamique systématique.</td></tr>\n        </tbody>\n      </table>\n      <h4>Gravité gazométrique</h4>\n      <ul>\n        <li>La DRA s'accompagne le plus souvent d'une <span class=\"kw-bio\">hypocapnie</span> (hyperventilation alvéolaire réflexe à l'hypoxémie) ;</li>\n        <li>L'<span class=\"kw-alerte\">acidose respiratoire</span> secondaire à l'hypercapnie témoigne d'une gravité supplémentaire.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Piège majeur.</strong> Une <span class=\"kw-alerte\">normocapnie est anormale</span> dans une <span class=\"kw-alerte\">détresse</span> respiratoire : elle a la <strong>même valeur de gravité qu'une hypercapnie</strong>. L'hypercapnie ne se voit que dans 2 situations : <span class=\"kw-etio\">décompensation d'insuffisance respiratoire chronique</span> et <span class=\"kw-etio\">épuisement respiratoire</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 331 — Arrêt cardio-circulatoire</em></p>","frequence":9},{"id":"359-7","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître les signes de détresse respiratoires suite à l’inhalation d’un corps étranger chez l’enfant et chez l’adulte, ou en cas d’épiglottite de l’enfant et de l’adulte","contenu":"<p>L'inhalation d'un <span class=\"kw-def\">corps étranger (CE)</span> est une <span class=\"kw-alerte\">urgence extrême</span>. Le tableau initial est le <strong><span class=\"kw-clinique\">syndrome de pénétration</span></strong>.</p>\n      <h4><span class=\"kw-clinique\">Syndrome de pénétration</span> (ou syndrome d'inhalation)</h4>\n      <ul>\n        <li>Survient chez un individu antérieurement sain, au cours d'un <strong>repas</strong> ou d'un <strong>jeu</strong> ; début <strong>brutal</strong> ;</li>\n        <li>Patient <span class=\"kw-clinique\">paniqué, agité</span>, portant <span class=\"kw-clinique\">les</span> mains au cou, gesticulant sans émettre de son ;</li>\n        <li><span class=\"kw-clinique\">Toux quinteuse</span>, <span class=\"kw-clinique\">tirage inspiratoire</span> entre <span class=\"kw-clinique\">les</span> quintes, accès de suffocation (<span class=\"kw-clinique\">tirage</span>, <span class=\"kw-clinique\">cornage</span>, puis <span class=\"kw-alerte\">malaise</span> et <span class=\"kw-alerte\">cyanose</span>) ;</li>\n        <li><span class=\"kw-clinique\">Dysphonie</span> (voire <span class=\"kw-alerte\">aphonie</span> si obstruction totale), <span class=\"kw-clinique\">bradypnée inspiratoire</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Localisation du CE</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Nasal</strong></td><td><span class=\"kw-clinique\">Dyspnée</span> inspiratoire, inspiration buccale, ronflement.</td></tr>\n          <tr><td><strong>Laryngé</strong></td><td><span class=\"kw-clinique\">Dyspnée</span> inspiratoire, <span class=\"kw-clinique\">stridor</span> (aigu) ou <span class=\"kw-clinique\">cornage</span> (rauque, sous-glottique), <span class=\"kw-clinique\">toux</span> permanente.</td></tr>\n          <tr><td><strong>Trachéal</strong></td><td><span class=\"kw-clinique\">Dyspnée</span> inspiratoire <strong>et</strong> expiratoire, <span class=\"kw-clinique\">cornage</span>, <span class=\"kw-clinique\">toux</span> aboyante ou coqueluchoïde.</td></tr>\n          <tr><td><strong>Bronchique</strong></td><td><span class=\"kw-clinique\">Dyspnée</span> expiratoire, <span class=\"kw-clinique\">wheezing</span>, <span class=\"kw-clinique\">râles sibilants ou sous-crépitants unilatéraux</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Épiglottite (à distinguer).</strong> <span class=\"kw-alerte\">Détresse</span> respiratoire à début brutal avec <span class=\"kw-alerte\">tirage</span> et cornage, mais en faveur de l'épiglottite : <span class=\"kw-clinique\">fièvre élevée</span>, <span class=\"kw-clinique\">voix étouffée</span>, <span class=\"kw-clinique\">hypersalivation</span>, <span class=\"kw-clinique\">toux absente</span>, bouche demi-ouverte, majoration de la <span class=\"kw-clinique\">dyspnée</span> au <strong>décubitus</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke - <span class=\"kw-alerte\">anaphylaxie</span></em></p>","frequence":0},{"id":"359-8","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","contenu":"<p>Aucun élément n'est formel ou absolu : c'est un <strong>faisceau d'arguments</strong> anamnestiques et cliniques qui oriente vers l'étiologie.</p>\n      <h4>Chez l'adulte — EP / <span class=\"kw-imagerie\">pneumothorax</span> / <span class=\"kw-def\"><span class=\"kw-def\">asthme</span> aigu grave</span></h4>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-def\">Embolie pulmonaire</span></th><th><span class=\"kw-imagerie\">Pneumothorax</span></th><th><span class=\"kw-def\"><span class=\"kw-def\">Asthme</span> aigu grave</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antécédents</strong></td><td><span class=\"kw-etio\">FdR de maladie thrombo-embolique</span></td><td>Sujet longiligne, <span class=\"kw-etio\">tabac / cannabis</span>, pathologie respiratoire « à risque »</td><td><span class=\"kw-etio\">Asthme connu</span></td></tr>\n          <tr><td><strong>Début</strong></td><td>Rapide voire brutal</td><td>Brutal, parfois après un effort</td><td>Perte de contrôle de l'<span class=\"kw-def\">asthme</span> / exacerbation</td></tr>\n          <tr><td><strong>Signes fonctionnels</strong></td><td><span class=\"kw-clinique\">Douleur latéro-thoracique</span> majorée à l'inspiration, <span class=\"kw-clinique\">toux</span> non productive, <span class=\"kw-clinique\">hémoptysie</span> (rare)</td><td><span class=\"kw-clinique\">Douleur latéro-thoracique</span>, <span class=\"kw-clinique\">toux</span> non productive</td><td><span class=\"kw-clinique\">Freinage expiratoire</span></td></tr>\n          <tr><td><strong>Examen</strong></td><td>Auscultation normale, <span class=\"kw-clinique\">turgescence jugulaire</span> (IVD)</td><td><span class=\"kw-clinique\">Abolition du murmure vésiculaire</span>, <span class=\"kw-clinique\">tympanisme</span></td><td><span class=\"kw-clinique\">Sibilants</span> ou <span class=\"kw-alerte\">silence auscultatoire</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Radiographie</span></strong></td><td>Souvent normale ; atélectasie en bande, opacité périphérique</td><td><span class=\"kw-imagerie\">Hyperclarté</span> délimitée par une ligne pleurale</td><td><span class=\"kw-imagerie\">Distension thoracique</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Chez l'adulte — <span class=\"kw-def\">pneumonie</span> / <span class=\"kw-def\">OAP</span> cardiogénique</h4>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-def\">Pneumonie</span> infectieuse</th><th><span class=\"kw-def\">OAP</span> cardiogénique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antécédents</strong></td><td>Aucun ; parfois immunodépression</td><td><span class=\"kw-etio\">Insuffisance cardiaque</span>, FdR cardio-vasculaires</td></tr>\n          <tr><td><strong>Signes généraux</strong></td><td><span class=\"kw-clinique\">Fièvre élevée</span>, <span class=\"kw-clinique\">frissons</span></td><td>Aucun</td></tr>\n          <tr><td><strong>Signes fonctionnels</strong></td><td><span class=\"kw-clinique\">Expectoration</span> purulente, douleur rythmée par la respiration</td><td><span class=\"kw-clinique\">Expectoration</span> mousseuse parfois rosée, <span class=\"kw-clinique\">orthopnée</span></td></tr>\n          <tr><td><strong>Examen</strong></td><td>Foyer de <span class=\"kw-clinique\">râles crépitants</span></td><td><span class=\"kw-clinique\">Crépitants bilatéraux</span> des bases, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-def\">HTA</span></td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-def\">Syndrome inflammatoire</span>, <span class=\"kw-bio\">hyperleucocytose</span>, ↑ <span class=\"kw-bio\">PCT</span>, antigénuries</td><td>Élévation du <span class=\"kw-bio\">BNP / NT-proBNP</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Chez l'enfant — orientation par le type de <span class=\"kw-clinique\">dyspnée</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Dyspnée</span> bruyante</strong> : oriente vers une obstruction (laryngée, trachéale ou bronchique selon le bruit) ;</li>\n        <li><strong><span class=\"kw-clinique\">Dyspnée</span> non bruyante</strong> avec auscultation anormale : <span class=\"kw-etio\">pneumopathie</span>, <span class=\"kw-etio\">pleurésie</span>, <span class=\"kw-etio\">pneumothorax</span>, <span class=\"kw-etio\">bronchiolite</span>, <span class=\"kw-etio\">myocardite / OAP</span> ;</li>\n        <li><strong><span class=\"kw-clinique\">Dyspnée</span> sine materia</strong> (auscultation normale) : <span class=\"kw-etio\">acidocétose diabétique</span>, <span class=\"kw-etio\">anémie</span>, <span class=\"kw-etio\">état de choc</span>, <span class=\"kw-clinique\">hyperthermie</span>, causes psychogènes.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 203 — <span class=\"kw-clinique\">Dyspnée</span></em></p>","frequence":1},{"id":"359-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","contenu":"<p>Première étape obl<span class=\"kw-chiffre\">iga</span>toire : <strong>éliminer une obstruction des voies aériennes supérieures</strong>.</p>\n      <div class=\"callout callout-info\"><strong>Quand ?</strong> Le bilan étiologique est réalisé <span class=\"kw-alerte\">après la prise en charge symptomatique</span> (<span class=\"kw-ttt\">oxygénothérapie</span> ± ventilation mécanique) — jamais avant.</div>\n      <table >\n        <thead><tr><th>Examen</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bilan de base</strong></td><td><span class=\"kw-imagerie\">Radiographie thoracique</span> ; <span class=\"kw-bio\">gaz du sang</span> ; <span class=\"kw-bio\">lactates</span> ; <span class=\"kw-bio\">ECG</span>.</td></tr>\n          <tr><td><strong>Selon le contexte</strong></td><td><span class=\"kw-imagerie\">ETT</span> (<span class=\"kw-def\">OAP</span>) ; <span class=\"kw-imagerie\">TDM thoracique</span> (EP, PID) ; <span class=\"kw-imagerie\">scanner cervical</span> si obstruction des VAS.</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Gazométrie</span></strong></td><td>Hypoxémie = <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&lt; 80 mmHg</span> en <span class=\"kw-def\">air</span> ambiant, ou <span class=\"kw-bio\">PaO2/FiO2</span> <span class=\"kw-chiffre\">&lt; 300</span>. <span class=\"kw-bio\">Hypocapnie</span> habituelle ; normocapnie / hypercapnie = gravité.</td></tr>\n        </tbody>\n      </table>\n      <h4>Orientation selon la <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span></h4>\n      <table >\n        <thead><tr><th><span class=\"kw-imagerie\">RXT</span></th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Avec anomalies</strong></td><td><span class=\"kw-etio\">Pneumonie infectieuse</span> ; <span class=\"kw-etio\">OAP</span> ; <span class=\"kw-etio\">pneumothorax sous tension</span> ; <span class=\"kw-alerte\">SDRA</span> ; exacerbation de <span class=\"kw-etio\">PID</span>.</td></tr>\n          <tr><td><strong>Sans anomalie</strong></td><td>Pathologie aiguë « de novo » : <span class=\"kw-etio\">embolie pulmonaire</span>, <span class=\"kw-etio\">pneumothorax</span>, <span class=\"kw-etio\">asthme aigu grave</span>, <span class=\"kw-etio\">état de choc</span>.<br><span class=\"kw-alerte\">Décompensation</span> d'une pathologie respiratoire chronique : évoquée devant une <span class=\"kw-bio\">hypercapnie</span> (<span class=\"kw-chiffre\">PaCO2 ≥ 45 mmHg</span>) à <span class=\"kw-bio\">pH</span> normal, et une élévation des <span class=\"kw-bio\">bicarbonates</span> (<span class=\"kw-chiffre\">HCO3⁻ &gt; 30 mmol/L</span> = hypercapnie chronique).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une <span class=\"kw-etio\">pneumonie infectieuse</span> peut évoluer vers un <span class=\"kw-alerte\">SDRA</span> — y penser devant une aggravation.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 209 — <span class=\"kw-def\">BPCO</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 154 — Infection bronchopulmonaire communautaire · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":3},{"id":"359-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant un corps étranger bronchique","contenu":"<p>L'imagerie ne doit <strong>jamais retarder</strong> le traitement en <span class=\"kw-alerte\">urgence</span> : elle est réalisée après <span class=\"kw-clinique\">les</span> mesures d'urgence.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication / résultats</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">RXT</span> inspiration</strong></td><td>Réalisée en premier. <span class=\"kw-imagerie\">Normale le plus souvent</span> (ou faussement normale <span class=\"kw-clinique\">les</span> premières heures) si enclavement dans les voies aériennes.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">RXT</span> expiration</strong></td><td>Réalisée seulement si la <span class=\"kw-imagerie\">RXT</span> en inspiration est normale : plus sensible pour détecter le <span class=\"kw-imagerie\">piégeage d'air</span>.</td></tr>\n          <tr><td><strong>Signes possibles</strong></td><td><strong>CE radio-opaque :</strong> visible directement (≈ <span class=\"kw-chiffre\">10 %</span> des cas)<br><strong>Obstacle complet :</strong> <span class=\"kw-imagerie\">atélectasie</span> — opacité dense rétractile systématisée, attraction médiastinale homolatérale<br><strong>Obstacle incomplet :</strong> <span class=\"kw-imagerie\">emphysème obstructif localisé</span> — hyperclarté unilatérale majorée en expiration, distension, refoulement médiastinal controlatéral</td></tr>\n          <tr><td><strong>Si doute</strong></td><td><span class=\"kw-imagerie\">Scanner thoracique</span> ou <span class=\"kw-imagerie\">fibroscopie bronchique</span> (confirmation et extraction).</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"359-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration en imagerie et échographie devant une détresse respiratoire néonatale","contenu":"<div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucun contenu correspondant à la stratégie d'imagerie et d'<span class=\"kw-imagerie\">échographie</span> de la <span class=\"kw-alerte\">détresse</span> respiratoire <strong>néonatale</strong> n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>359-detresse-insuffisance-respiratoire-aigue/</code>. Kevin enrichira ce paragraphe depuis le Collège de Pédiatrie (<span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span> néonatale, <span class=\"kw-imagerie\">échographie</span> pulmonaire, recherche de maladie des membranes hyalines / retard de résorption / inhalation méconiale).</div>\n      <!-- TODO Kevin : stratégie imagerie + <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">échographie</span></span> DR néonatale -->","frequence":0},{"id":"359-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration en imagerie devant une détresse respiratoire du nourrisson et de l’enfant","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">Radiographie thoracique</span></strong></td><td>Systématique dès qu'il existe un <strong>doute diagnostique</strong> ou dès que la <span class=\"kw-alerte\">DRA est sévère</span> (indications précisées dans chaque pathologie).</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Gaz du sang veineux</span></strong></td><td><span class=\"kw-etio\">Acidocétose diabétique</span> ; signes d'hypoventilation pour évaluer la capnie : <span class=\"kw-clinique\">apnées</span>, <span class=\"kw-clinique\">pauses respiratoires</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">troubles de la conscience</span>.</td></tr>\n          <tr><td><strong>Autres</strong></td><td><span class=\"kw-bio\">Glycémie capillaire</span> : <span class=\"kw-clinique\">dyspnée</span> sine materia<br><span class=\"kw-bio\">NFS</span> : <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-def\">sepsis</span>, <span class=\"kw-clinique\">fièvre</span> avant <span class=\"kw-chiffre\">3 mois</span>, <span class=\"kw-etio\">drépanocytose</span><br><span class=\"kw-imagerie\">Endoscopie bronchique</span> : suspicion de corps étranger inhalé</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"359-13","rang":"A","rubrique":"Contenu multimédia","titre":"Savoir reconnaître un OAP sur une radiographie du thorax","contenu":"<p>Sur une <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span>, l'<span class=\"kw-def\">œdème aigu pulmonaire cardiogénique</span> se traduit par des <span class=\"kw-imagerie\">opacités alvéolaires bilatérales, diffuses, à prédominance péri-hilaire</span>.</p>\n      <ul>\n        <li>Répartition <strong>bilatérale et symétrique</strong>, péri-hilaire (« en ailes de papillon ») ;</li>\n        <li>S'accompagne du contexte clinique : <span class=\"kw-clinique\">orthopnée</span>, <span class=\"kw-clinique\">crépitants bilatéraux</span> des bases, élévation du <span class=\"kw-bio\">BNP / NT-proBNP</span>, antécédents d'<span class=\"kw-etio\">insuffisance cardiaque</span> ou de FdR cardio-vasculaires.</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/359/rxt-oap-cardiogenique.png\" alt=\"Radiographie thoracique d'un œdème aigu pulmonaire cardiogénique : opacités alvéolaires bilatérales péri-hilaires\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">RP</span> d'<span class=\"kw-def\">OAP</span> cardiogénique : <span class=\"kw-radio\">opacités alvéolaires bilatérales péri-hilaires « en ailes de papillon »</span>, redistribution vasculaire vers <span class=\"kw-clinique\">les</span> sommets et lignes de Kerley (radio de face au lit + zoom debout). Source : banque iconographique officielle EDN (« Imagerie à connaître »).</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span></em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/airway-foreign-bodies-in-children","label":"Radiopaedia : Airway foreign bodies in children"}]},{"id":"359-14","rang":"A","rubrique":"Contenu multimédia","titre":"Savoir reconnaître une pneumonie sur une radiographie du thorax","contenu":"<p>Sur une <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span>, la <span class=\"kw-def\">pneumonie infectieuse</span> se traduit par des <span class=\"kw-imagerie\">opacités alvéolaires souvent systématisées</span> — mais pas toujours.</p>\n      <ul>\n        <li>Opacité <strong>de topographie systématisée</strong> (un lobe, un segment), volontiers unique, à bord flou ;</li>\n        <li>Contexte clinique : <span class=\"kw-clinique\">fièvre élevée</span>, <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-clinique\">foyer de râles crépitants</span>, <span class=\"kw-bio\">syndrome inflammatoire</span> ;</li>\n        <li>À distinguer de l'<span class=\"kw-def\">OAP</span> (opacités bilatérales diffuses péri-hilaires, sans systématisation).</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/359/rxt-pneumonie.png\" alt=\"Radiographie thoracique d'une pneumonie : opacité alvéolaire systématisée\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">RP</span> de <span class=\"kw-def\">pneumonie</span> : <span class=\"kw-radio\">opacité alvéolaire systématisée à bord flou avec bronchogramme aérique</span> — pneumonie franche lobaire aiguë du LSD (à gauche) et pneumonie du LID (à droite). Source : banque iconographique officielle EDN (« Imagerie à connaître »).</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire</em></p>","frequence":0},{"id":"359-15","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies à l’origine de la détresse respiratoire aiguë du nourrisson et de l’enfant","contenu":"<p>Chez le nourrisson et l'enfant, il s'agit le plus souvent d'une <span class=\"kw-etio\">infection des voies aériennes</span> ou d'une <span class=\"kw-etio\">crise d'asthme</span>. Toute <span class=\"kw-clinique\">dyspnée</span> d'installation brutale après <span class=\"kw-chiffre\">6 mois</span> fait évoquer une <span class=\"kw-alerte\">inhalation de corps étranger</span> ; la recherche de signes d'<span class=\"kw-etio\">insuffisance cardiaque aiguë</span> doit être systématique.</p>\n      <table >\n        <thead><tr><th>Type de <span class=\"kw-clinique\">dyspnée</span></th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bruyante laryngée</strong> (inspiratoire)</td><td><span class=\"kw-etio\">Rhinopharyngite obstructive</span> ; <span class=\"kw-etio\">laryngomalacie</span> ; <span class=\"kw-etio\">amygdalite / abcès rétro-pharyngé</span> ; <span class=\"kw-etio\">laryngite sous-glottique</span>.</td></tr>\n          <tr><td><strong>Bruyante laryngée — <span class=\"kw-alerte\">urgence</span></strong></td><td><span class=\"kw-alerte\">Épiglottite</span> ; <span class=\"kw-alerte\">CE laryngé</span> ; <span class=\"kw-alerte\">œdème laryngé sur anaphylaxie</span> ; <span class=\"kw-etio\">coqueluche</span>.</td></tr>\n          <tr><td><strong>Bruyante trachéale</strong></td><td><span class=\"kw-etio\">Compression trachéale extrinsèque</span> ; <span class=\"kw-etio\">CE trachéal</span> ; <span class=\"kw-etio\">sténose trachéale</span>.</td></tr>\n          <tr><td><strong>Bruyante bronchique</strong> (expiratoire)</td><td><span class=\"kw-etio\">CE bronchique</span> ; <span class=\"kw-etio\">bronchiolite</span> ; <span class=\"kw-etio\">asthme</span>.</td></tr>\n          <tr><td><strong>Non bruyante</strong></td><td><span class=\"kw-etio\">Pneumopathie</span> ; <span class=\"kw-etio\">pleurésie</span> ; <span class=\"kw-etio\">pneumothorax</span> ; <span class=\"kw-etio\">myocardite / insuffisance cardiaque / OAP</span>.</td></tr>\n          <tr><td><strong>Sine materia</strong> (auscultation normale)</td><td><span class=\"kw-etio\">Acidocétose diabétique</span> ; <span class=\"kw-clinique\">hyperthermie</span> ; <span class=\"kw-etio\">état de choc</span> ; <span class=\"kw-etio\">anémie</span> ; causes neuro-méningées ; causes psychogènes.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\"><span class=\"kw-def\">Insuffisance cardiaque</span> aiguë</span> de l'enfant.</strong> À évoquer surtout chez le nourrisson : <span class=\"kw-etio\">shunts gauche-droit</span> (CIV, CAV, PCA), <span class=\"kw-etio\">myocardites infectieuses</span>, <span class=\"kw-etio\">troubles du rythme</span> (tachycardies supraventriculaires). Signe négatif utile : pas de <span class=\"kw-clinique\">fièvre</span>, sauf myocardite infectieuse.</div>","frequence":1},{"id":"359-16","rang":"A","rubrique":"Étiologies","titre":"Savoir reconnaître les causes les plus fréquentes chez l’adulte","contenu":"<p>Chez l'adulte, six grandes causes dominent la <span class=\"kw-alerte\">détresse respiratoire aiguë</span>. La <span class=\"kw-imagerie\">radiographie thoracique</span> est la clé du tri étiologique.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-imagerie\">RXT</span></th><th>Causes fréquentes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Avec anomalie</strong></td>\n            <td><span class=\"kw-etio\">Pneumonie infectieuse</span> : <span class=\"kw-clinique\">fièvre</span>, foyer de <span class=\"kw-clinique\">crépitants</span>, opacité systématisée<br><span class=\"kw-etio\">OAP cardiogénique</span> : <span class=\"kw-clinique\">orthopnée</span>, <span class=\"kw-clinique\">crépitants</span> bilatéraux, ↑ <span class=\"kw-bio\">BNP</span><br><span class=\"kw-etio\">Pneumothorax sous tension</span> : <span class=\"kw-alerte\">urgence</span> vitale</td>\n          </tr>\n          <tr>\n            <td><strong>Sans anomalie</strong></td>\n            <td><span class=\"kw-etio\">Embolie pulmonaire</span> : FdR thrombo-emboliques, auscultation normale<br><span class=\"kw-etio\">Pneumothorax</span> : sujet longiligne, abolition du murmure vésiculaire<br><span class=\"kw-etio\">Asthme aigu grave</span> : <span class=\"kw-clinique\">sibilants</span> ou silence auscultatoire</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Penser aussi à la <span class=\"kw-etio\">décompensation aiguë de BPCO</span> : <span class=\"kw-bio\">hypercapnie</span> avec <span class=\"kw-bio\">pH</span> normal et <span class=\"kw-bio\">bicarbonates</span> élevés. <span class=\"kw-clinique\">Les</span> tableaux comparatifs détaillés EP / PNO / <span class=\"kw-def\">asthme</span> et <span class=\"kw-def\">pneumonie</span> / <span class=\"kw-def\">OAP</span> sont développés dans l'objectif « éléments d'orientation clinique ».</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 209 — <span class=\"kw-def\">BPCO</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 154 — Infection bronchopulmonaire communautaire · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 360 — <span class=\"kw-imagerie\">Pneumothorax</span></em></p>","frequence":2},{"id":"359-17","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les premiers gestes chez l’enfant présentant une détresse respiratoire d’origine ORL","contenu":"<h4>Mesures urgentes — quel que soit le diagnostic</h4>\n      <ul>\n        <li><strong>Libération des voies aériennes supérieures</strong> : retrait d'un corps étranger, aspiration, désobstruction rhinopharyngée ;</li>\n        <li>Mise en position <span class=\"kw-ttt\">proclive</span> (nourrisson) ou <span class=\"kw-ttt\">semi-assise</span> (enfant) — <span class=\"kw-ci\">ne jamais allonger</span> un enfant en <span class=\"kw-alerte\">détresse</span> respiratoire ;</li>\n        <li><span class=\"kw-ttt\">Oxygénothérapie</span> adaptée à la <span class=\"kw-bio\">SpO2</span> ; <span class=\"kw-ttt\">VVP</span> si retentissement hémodynamique ; transfert médicalisé (<span class=\"kw-alerte\">SAMU</span>) / USI si besoin.</li>\n      </ul>\n      <h4>Obstruction des VAS par un corps étranger</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Toux</span> efficace</strong></td><td>Encourager à tousser et surveiller.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Toux</span> inefficace — conscient</strong></td><td>Manœuvres d'expulsion : <span class=\"kw-chiffre\">5</span> tapes dorsales puis <span class=\"kw-chiffre\">5</span> compressions — <strong>thoraciques</strong> chez le nourrisson, <strong>abdominales</strong> chez l'enfant.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Toux</span> inefficace — inconscient</strong></td><td>Libérer <span class=\"kw-clinique\">les</span> voies aériennes, <span class=\"kw-chiffre\">5</span> insufflations, démarrer la <span class=\"kw-ttt\">RCP</span>.</td></tr>\n          <tr><td><strong>Nourrisson &lt;<span class=\"kw-chiffre\"> 2 ans</span></strong></td><td><span class=\"kw-ttt\">Manœuvre de Mofenson</span> (5 tapes dorsales + 5 compressions thoraciques) — la manœuvre de Heimlich est <span class=\"kw-ci\">contre-indiquée</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> En cas d'<span class=\"kw-alerte\">œdème de Quincke obstructif</span> : <span class=\"kw-ttt\">adrénaline IM 0,5 mg</span> immédiate.</div>","frequence":0},{"id":"359-18","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les premiers gestes chez l’adulte présentant une inhalation de corps étranger","contenu":"<p>Toujours considérer que le corps étranger est <strong>encore présent</strong> dans <span class=\"kw-clinique\">les</span> voies respiratoires (sauf si l'expulsion a été authentifiée par l'entourage).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Obstacle complet</strong><br>(<span class=\"kw-clinique\">toux</span> inefficace, <span class=\"kw-clinique\">cyanose</span>, risque d'<span class=\"kw-alerte\">arrêt cardiaque</span>)</td>\n            <td><strong>Patient conscient :</strong> <span class=\"kw-ttt\">manœuvre de Heimlich</span> — pression abdominale brutale au creux ép<span class=\"kw-chiffre\">iga</span>strique, mouvements de bas en haut, créant une hyperpression intra-thoracique<br><strong>Patient inconscient :</strong> allonger, rechercher un CE pharyngé volumineux, débuter la <span class=\"kw-ttt\">RCP</span> (plus efficace que Heimlich pour expulser un CE sur plan dur)</td>\n          </tr>\n          <tr>\n            <td><strong>Obstacle incomplet</strong><br>(ventilation spontanée possible : <span class=\"kw-alerte\">stridor</span>, cornage, <span class=\"kw-clinique\">wheezing</span>)</td>\n            <td><span class=\"kw-ci\">Éviter toute mobilisation</span> : respecter la position spontanément choisie<br><span class=\"kw-ci\">Manœuvres d'expulsion proscrites</span> (risque de mobilisation du CE)<br>Respecter la <span class=\"kw-clinique\">toux</span> efficace, position demi-assise, <span class=\"kw-ttt\">oxygénothérapie</span>, orientation vers un plateau technique (<span class=\"kw-imagerie\">fibroscopie</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mesures associées.</strong> Appel des secours (<span class=\"kw-alerte\">SAMU</span>), arrêt de la prise d'aliments et de boissons, monitoring.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 331 — Arrêt cardio-circulatoire</em></p>","frequence":0},{"id":"359-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités d’oxygénation initiale","contenu":"<p>Premier réflexe : <strong>éliminer un corps étranger des VAS</strong>. Puis : appel <span class=\"kw-alerte\">SAMU</span> / réanimateur, arrêt alimentation-boissons, <span class=\"kw-ttt\">monitoring</span> (<span class=\"kw-bio\">SpO2</span> continue, FC, PA, FR toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 min</span>), <span class=\"kw-ttt\">VVP de gros calibre</span>.</p>\n      <p>L'<span class=\"kw-ttt\">oxygénothérapie</span> est <strong>systématique</strong> : elle corr<span class=\"kw-chiffre\">ige</span> l'hypoxémie pour prévenir l'<span class=\"kw-alerte\">arrêt cardio-respiratoire</span> hypoxique.</p>\n      <ul>\n        <li>Objectif : <span class=\"kw-chiffre\">SpO2 &gt; 90 %</span> ;</li>\n        <li><span class=\"kw-def\">IRA</span> <strong>hypercapnique</strong> → O2 par <span class=\"kw-ttt\">VNI</span> ;</li>\n        <li><span class=\"kw-def\">IRA</span> <strong>hypoxémique</strong> → O2 à haut débit par <span class=\"kw-ttt\">masque à haute concentration</span> (<span class=\"kw-chiffre\">12-15 L/min</span>), débit ensuite adapté à la clinique ;</li>\n        <li><span class=\"kw-bio\">Gaz du sang</span> de contrôle lorsque la <span class=\"kw-bio\">SpO2</span> est entre <span class=\"kw-chiffre\">92-96 %</span> (risque inconstant d'hypercapnie par inhibition des centres respiratoires).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Focus <span class=\"kw-def\">BPCO</span>.</strong> L'<span class=\"kw-ttt\">oxygénothérapie</span> n'est <strong>pas <span class=\"kw-etio\">toxique</span></strong> chez le <span class=\"kw-def\">BPCO</span> : il n'existe pas de débit minimal. Seule la cible de saturation est adaptée — <span class=\"kw-chiffre\">SaO2 cible 88-92 %</span>. Ne jamais sous-doser l'O2 par peur de la capnie : l'<span class=\"kw-alerte\">hypoxémie tue immédiatement</span>, pas l'hypercapnie.</div>\n      <table >\n        <thead><tr><th>Interface</th><th>Débit / FiO2</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Lunettes nasales</strong></td><td><span class=\"kw-chiffre\">1-6 L/min</span></td><td>Hypoxémie en situation stable.</td></tr>\n          <tr><td><strong>Masque simple</strong></td><td><span class=\"kw-chiffre\">4-8 L/min</span></td><td>Hypoxémie modérée en situation stable.</td></tr>\n          <tr><td><strong>Masque à réserve</strong> (haute concentration)</td><td><span class=\"kw-chiffre\">8-15 L/min</span></td><td><span class=\"kw-def\">IRA</span> hypoxémique en <strong>1ʳᵉ intention</strong> ; hypoxémie sévère.</td></tr>\n          <tr><td><strong>Haut débit nasal</strong></td><td><span class=\"kw-chiffre\">10-70 L/min</span>, FiO2 <span class=\"kw-chiffre\">21-100 %</span></td><td>Hypoxémie sévère (<span class=\"kw-def\">pneumonie</span> hypoxémique) ; pré-oxygénation.</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">VNI</span></strong></td><td>FiO2 <span class=\"kw-chiffre\">21-100 %</span></td><td><span class=\"kw-def\">IRA</span> hypercapnique ; <span class=\"kw-def\">OAP</span> cardiogénique ; exacerbation de <span class=\"kw-def\">BPCO</span> avec acidose.</td></tr>\n          <tr><td><strong>Ventilation invasive</strong></td><td>FiO2 <span class=\"kw-chiffre\">21-100 %</span></td><td><span class=\"kw-alerte\">Détresse</span> persistante / non isolée ; échec de <span class=\"kw-ttt\">VNI</span> ; <span class=\"kw-clinique\">coma</span>, <span class=\"kw-alerte\">choc</span>, ACR.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Un besoin <span class=\"kw-chiffre\">&gt; 5 L/min</span> d'O2 impose de <strong>contacter le réanimateur</strong>.</div>","frequence":4},{"id":"359-20","rang":"B","rubrique":"Prise en charge","titre":"Connaître les différents moyens de la prise en charge d’un patient en insuffisance respiratoire aiguë","contenu":"<p>L'<span class=\"kw-def\">assistance ventilatoire</span> consiste à administrer une pression positive inspiratoire (<span class=\"kw-def\">air</span> + O2) via un respirateur, pour remplacer <span class=\"kw-clinique\">les</span> muscles respiratoires et éviter la fermeture des alvéoles.</p>\n      <div class=\"callout callout-info\"><strong>Indications de l'assistance ventilatoire.</strong> Hypoxémie réfractaire à l'<span class=\"kw-ttt\">oxygénothérapie</span> (<span class=\"kw-chiffre\">SpO2 &lt; 90 %</span>) ; hypoventilation aiguë menaçant le <span class=\"kw-alerte\">pronostic vital</span> — 3 signes : <span class=\"kw-alerte\">respiration paradoxale</span>, <span class=\"kw-alerte\">troubles de la conscience</span>, <span class=\"kw-alerte\">acidose respiratoire</span>. L'expiration abdominale active n'est <span class=\"kw-ci\">pas une indication de VNI</span>.</div>\n      <table >\n        <thead><tr><th>Technique</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">VNI</span></strong><br>(ventilation non invasive)</td>\n            <td>Réservée aux défaillances respiratoires <strong>isolées</strong> chez un patient conscient et coopérant.<br><strong>Indications :</strong> <span class=\"kw-etio\">OAP cardiogénique</span> ; <span class=\"kw-etio\">exacerbation de BPCO</span> en acidose respiratoire (<span class=\"kw-chiffre\">pH &lt; 7,35</span>) ; pré-oxygénation.<br><strong>Intérêt majeur :</strong> réduit <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">infections nosocomiales respiratoires</span>, la morbi-<span class=\"kw-def\">mortalité</span> et la durée d'<span class=\"kw-alerte\">hospitalisation</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Ventilation invasive</span></strong><br>(sonde d'<span class=\"kw-ttt\">intubation</span>)</td>\n            <td>D'emblée si la <span class=\"kw-alerte\">défaillance</span> n'est <strong>pas isolée</strong> : <span class=\"kw-alerte\">troubles de conscience</span>, <span class=\"kw-alerte\">état de choc</span>, <span class=\"kw-alerte\">polytraumatisme</span>, défaillance multi-organes, <span class=\"kw-alerte\">Glasgow ≤ 8</span>, <span class=\"kw-alerte\">ACR</span>.<br>En 2ᵉ intention après <strong>échec de la <span class=\"kw-ttt\">VNI</span></strong>, ou en cas d'épuisement respiratoire (<span class=\"kw-clinique\">bradypnée</span> asphyxique, balancement thoraco-abdominal).</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Effets bénéfiques de la <span class=\"kw-ttt\">VNI</span> dans l'<span class=\"kw-def\">OAP</span> cardiogénique</h4>\n      <ul>\n        <li><strong>Effets hémodynamiques</strong> : ↑ pression intrathoracique → <strong>diminution de la précharge</strong> (gêne le retour veineux) et <strong>de la postcharge VG</strong> — effets comparables aux <span class=\"kw-ttt\">diurétiques</span> + dérivés <span class=\"kw-ttt\">nitrés</span> ;</li>\n        <li><strong>Effets respiratoires</strong> : ↑ proportion d'O2 inspiré, <strong>diminution du travail respiratoire</strong> (↓ consommation d'O2) ;</li>\n        <li>Techniques : aide inspiratoire + <span class=\"kw-ttt\">PEP</span>, ou <span class=\"kw-ttt\">CPAP</span> ; séances typiques de <span class=\"kw-chiffre\">1 h</span> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 h</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Autres modalités.</strong> <span class=\"kw-ttt\">ECMO</span> : oxygénation par voie vasculaire via une circulation extra-corporelle. <span class=\"kw-ttt\">Oxygénothérapie hyperbare</span> : O2 à des niveaux très élevés.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":4},{"id":"359-21","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir orienter en urgence un patient en détresse respiratoire aiguë pour un geste spécialisé","contenu":"<p>Tout patient en <span class=\"kw-alerte\">détresse</span> respiratoire doit être conduit vers un <strong>centre disposant du plateau technique adapté</strong>. Deux situations imposent un geste spécialisé.</p>\n      <div class=\"callout callout-info\"><strong>Appel du réanimateur.</strong> Un besoin <span class=\"kw-chiffre\">&gt; 5 L/min</span> d'O2 impose de contacter le réanimateur ; toute <span class=\"kw-alerte\">détresse</span> persistante ou non isolée relève de la <span class=\"kw-alerte\">réanimation</span>.</div>\n      <h4>Extraction d'un corps étranger — <span class=\"kw-imagerie\">bronchoscopie</span></h4>\n      <p>L'extraction est réalisée en <strong>centre spécialisé</strong> (pédiatres, pneumologues, ORL). Une tentative d'extraction par du personnel non formé n'est <span class=\"kw-ci\">pas recommandée</span>.</p>\n      <table >\n        <thead><tr><th>Technique</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bronchoscopie rigide</strong><br>(technique de choix)</td><td>Après échec de la <span class=\"kw-imagerie\">bronchoscopie</span> souple, ou d'emblée si diagnostic quasi-certain (diminution unilatérale du murmure vésiculaire + piégeage ipsilatéral sur <span class=\"kw-imagerie\">RXT</span>). CE saisi à la pince rigide, ventilation assurée par le tube ; <span class=\"kw-ttt\">anesthésie générale</span> nécessaire chez l'enfant.</td></tr>\n          <tr><td><strong>Bronchoscopie souple</strong></td><td>Chez l'adulte si le CE n'est pas trop volumineux ; ou d'emblée si la probabilité d'un CE récent est faible (moins invasive).</td></tr>\n        </tbody>\n      </table>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence vitale</span> ; peut annoncer un <span class=\"kw-alerte\">arrêt cardio-respiratoire hypoxique</span><br><strong>Fenêtre :</strong> monitoring rapproché, <span class=\"kw-chiffre\">FR toutes les 10 min</span> ; <span class=\"kw-bio\">GDS</span> parfois <span class=\"kw-alerte\">faussement rassurants</span> (hypocapnie masquant une hypoxémie profonde) → à renouveler précocement<br><strong>1er geste :</strong> <span class=\"kw-ttt\">éliminer un corps étranger des VAS</span> puis <span class=\"kw-ttt\">oxygénothérapie</span> immédiate (objectif <span class=\"kw-chiffre\">SpO2 &gt; 90%</span>)</p>","hospit":"<p><strong>Pré-hospitalier :</strong> appel <span class=\"kw-ttt\">SAMU (15)</span><br><strong>Intra-hospitalier :</strong> appel du <span class=\"kw-ttt\">réanimateur</span> ; besoin de <span class=\"kw-chiffre\">&gt; 5 L/min d'O2</span> impose de contacter le réanimateur<br><strong>Geste spécialisé :</strong> orientation pour <span class=\"kw-ttt\">bronchoscopie</span> d'extraction (corps étranger) en centre spécialisé</p>","redflags":"<p><strong>Cliniques (signes de faillite)</strong></p><ul><li><span class=\"kw-clinique\">Cyanose</span> (Hb désoxygénée &gt;<span class=\"kw-chiffre\"> 5 g/dL</span>) = <span class=\"kw-alerte\">hypoxémie profonde</span>, <span class=\"kw-bio\">SaO2</span> <span class=\"kw-chiffre\">≤ 85%</span></li><li><span class=\"kw-clinique\">Respiration abdominale paradoxale</span> + <span class=\"kw-clinique\">orthopnée</span> → décubitus dorsal <span class=\"kw-ci\">contre-indiqué</span></li><li><span class=\"kw-clinique\">Balancement thoraco-abdominal</span> ; <span class=\"kw-alerte\">tirage</span> des muscles accessoires (faillite ventilatoire)</li><li><span class=\"kw-alerte\">Bradypnée asphyxique</span> ou irrégularités respiratoires = épuisement / <span class=\"kw-alerte\">défaillance</span> neurologique</li><li>Troubles de conscience, <span class=\"kw-def\">Glasgow</span> <span class=\"kw-chiffre\">≤ 8</span> → assistance ventilatoire</li><li>Signes circulatoires : <span class=\"kw-clinique\">cœur pulmonaire aigu</span>, <span class=\"kw-clinique\">pouls paradoxal</span> (↓ PAS <span class=\"kw-chiffre\">≥ 10 mmHg</span> à l'inspiration), <span class=\"kw-alerte\">état de choc</span></li></ul><p><strong>Gazométriques</strong></p><ul><li><span class=\"kw-bio\">PaO2 &lt; 60 mmHg</span> = IRA hypoxémique (type 1)</li><li><span class=\"kw-bio\">PaCO2 &gt; 45 mmHg</span> = IRA hypercapnique (type 2) → <span class=\"kw-alerte\">acidose respiratoire</span></li><li><span class=\"kw-alerte\">Normocapnie</span> dans une DRA : anormale, même valeur de gravité qu'une hypercapnie</li></ul><p><strong>Pédiatrie (<span class=\"kw-def\">terrain</span> & tolérance)</strong></p><ul><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-alerte\">âge &lt; 4-6 semaines</span>, prématurité, cardiopathie, drépanocytose, immunodépression</li><li><span class=\"kw-clinique\">SpO2 &lt; 92%</span>, geignement expiratoire, battement des ailes du nez, <span class=\"kw-alerte\">tirage</span>, entonnoir xiphoïdien</li><li>Mauvaise tolérance : <span class=\"kw-clinique\">TRC ≥ 3 s</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hépatomégalie</span>, épuisement avec hypo-réactivité</li></ul>","principes":"<p>Toujours la <strong>PEC symptomatique AVANT</strong> le <span class=\"kw-def\">diagnostic étiologique</span> ; <span class=\"kw-ttt\">oxygénothérapie</span> systématique.</p><p><strong>Mesures générales</strong></p><ul><li>Appel <span class=\"kw-ttt\">SAMU (15)</span> (extra-hospitalier) ou du <span class=\"kw-ttt\">réanimateur</span> (hôpital)</li><li>Arrêt de l'alimentation et des boissons</li><li>Monitoring : <span class=\"kw-clinique\">SaO2 continue</span>, FC, PA, <span class=\"kw-chiffre\">FR toutes les 10 min</span></li><li><span class=\"kw-ttt\">VVP de gros calibre</span> ; besoin de <span class=\"kw-chiffre\">&gt; 5 L/min d'O2</span> → contacter le réanimateur</li></ul><p><strong><span class=\"kw-ttt\">Oxygénothérapie</span> (objectif & interfaces)</strong></p><p>IRA hypercapnique → <span class=\"kw-ttt\">VNI</span>. Ne jamais sous-oxygéner un IRC par peur de la capnie : l'hypoxémie tue immédiatement, pas l'hypercapnie.</p><ul><li>Objectif <span class=\"kw-chiffre\">SpO2 &gt; 90%</span> ; <span class=\"kw-chiffre\">88-92%</span> chez le <span class=\"kw-etio\">BPCO</span> (l'O2 n'est pas <span class=\"kw-etio\">toxique</span>, on adapte la cible)</li><li><span class=\"kw-ttt\">Lunettes 1-6 L/min</span> ou <span class=\"kw-ttt\">masque simple 4-8 L/min</span> : hypoxémie stable</li><li><span class=\"kw-ttt\">Masque à haute concentration 8-15 L/min</span> : IRA hypoxémique en <span class=\"kw-chiffre\">1ère intention</span></li><li><span class=\"kw-ttt\">Haut débit nasal (OHD) 10-70 L/min</span>, FiO2 <span class=\"kw-chiffre\">21-100%</span> : hypoxémie sévère (pneumonie)</li><li><span class=\"kw-bio\">GDS</span> de contrôle quand <span class=\"kw-bio\">SpO2</span> <span class=\"kw-chiffre\">92-96%</span></li></ul><p><strong>Assistance ventilatoire — <span class=\"kw-ttt\">VNI</span> <span class=\"kw-bio\">vs</span> invasive</strong></p><p>3 signes d'hypoventilation menaçant le <span class=\"kw-alerte\">pronostic vital</span> → ventilation : respiration paradoxale, troubles de conscience, acidose respiratoire.</p><ul><li><span class=\"kw-ttt\">VNI</span> : <span class=\"kw-alerte\">défaillance</span> respiratoire <span class=\"kw-def\">isolée</span> chez patient conscient/coopérant — <span class=\"kw-etio\">OAP cardiogénique</span>, <span class=\"kw-etio\">exacerbation de BPCO</span> avec acidose (<span class=\"kw-bio\">pH</span> &lt; 7,35) ; réduit <span class=\"kw-clinique\">les</span> infections nosocomiales</li><li><span class=\"kw-ttt\">Ventilation invasive (intubation)</span> : <span class=\"kw-clinique\">Glasgow ≤ 8</span>, <span class=\"kw-alerte\">état de choc</span>, polytraumatisme, <span class=\"kw-alerte\">défaillance</span> multi-organe, échec de <span class=\"kw-ttt\">VNI</span></li><li>Épuisement (<span class=\"kw-alerte\">bradypnée asphyxique</span>, balancement thoraco-abdominal) → <span class=\"kw-ttt\">intubation</span></li></ul><p><strong>Corps étranger — désobstruction (1er réflexe)</strong></p><ul><li>Obstruction sévère (<span class=\"kw-clinique\">toux</span> inefficace) + conscient : <span class=\"kw-ttt\">Heimlich</span> (adulte / enfant) ; <span class=\"kw-ttt\">Mofenson</span> (5 tapes dorsales + 5 compressions thoraciques) chez le nourrisson &lt;<span class=\"kw-chiffre\"> 2 ans</span></li><li>Patient inconscient : libération des VAS, <span class=\"kw-ttt\">5 insufflations</span> puis <span class=\"kw-ttt\">RCP</span></li><li>Obstruction incomplète (<span class=\"kw-clinique\">toux</span> / ventilation possibles) : <span class=\"kw-ci\">ne pas mobiliser</span>, encourager la toux, O2, transfert pour <span class=\"kw-ttt\">bronchoscopie</span></li><li><span class=\"kw-clinique\">Œdème</span> de Quincke obstructif : <span class=\"kw-ttt\">adrénaline IM 0,5 mg</span> immédiate</li></ul><p><strong>Spécificités pédiatriques</strong></p><ul><li><span class=\"kw-ci\">Ne jamais allonger</span> un enfant en <span class=\"kw-alerte\">détresse</span> : proclive (nourrisson) ou semi-assis (enfant)</li><li>Libération des VAS (retrait CE, aspiration, DRP) ; <span class=\"kw-ttt\">oxygénothérapie</span> adaptée à la <span class=\"kw-bio\">SpO2</span></li><li>DRA + troubles hémodynamiques : <span class=\"kw-clinique\">palper le foie</span> avant tout remplissage vasculaire</li></ul>","suivi":"<p><strong>Monitoring :</strong> <span class=\"kw-clinique\">SaO2 continue</span>, FC, PA, <span class=\"kw-chiffre\">FR toutes les 10 min</span><br><strong><span class=\"kw-bio\">GDS</span> de contrôle :</strong> lorsque la <span class=\"kw-bio\">SpO2</span> est entre <span class=\"kw-chiffre\">92-96%</span> (risque inconstant d'<span class=\"kw-alerte\">hypercapnie</span> par levée du stimulus hypoxémique)<br><strong>Étiologie :</strong> bilan étiologique seulement <span class=\"kw-alerte\">après</span> la PEC symptomatique</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/10-ch01-001-016-9782294769580-1.pdf","label":"CeMIR — 10 ch01 001 016 9782294769580 1"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/detresse-respiratoire-aigue","label":"Pedia-univ — Detresse respiratoire aigue"},{"href":"https://www.ce-mir.fr/files/medias/documents/15.%20Insuffisance%20cardiaque%20et%20oed%C3%A8me%20aigu%20pulmonaire%20cardiog%C3%A9nique.pdf","label":"CeMIR — 15. insuffisance cardiaque et oedème aigu pulmonaire cardiogénique"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"DRA / IRA stabilisée — Bilan étiologique : RXT + GDS + lactates + ECG (après PEC symptomatique)","detail":"<h4>CAT — <span class=\"kw-def\">diagnostic étiologique</span> d'une DRA / IRA — Après stabilisation symptomatique (O2 ± ventilation) et exclusion d'un corps étranger</h4>","branches":[{"to":"q-rxt","label":"Patient stabilisé","color":"blue"}]},{"id":"q-rxt","kind":"decision","label":"Anomalie sur la radiographie thoracique ? — RXT réalisée après les mesures d'urgence","branches":[{"to":"q-opacite","label":"RXT anormale (opacités / hyperclarté)","color":"amber"},{"to":"q-capnie","label":"RXT normale ou subnormale","color":"blue"}]},{"id":"q-opacite","kind":"decision","label":"Quel type d'anomalie radiologique ?","branches":[{"to":"t-pneumonie","label":"Opacités systématisées + fièvre / foyer","color":"amber"},{"to":"t-oap","label":"Opacités bilatérales péri-hilaires + orthopnée","color":"red"},{"to":"t-pno","label":"Hyperclarté + tympanisme + abolition MV","color":"red"}]},{"id":"t-pneumonie","kind":"terminal","label":"Pneumonie infectieuse → antibiothérapie urgente","color":"amber","detail":"<h4>Orientation</h4><ul><li>Début brutal, <span class=\"kw-clinique\">fièvre élevée</span> et <span class=\"kw-clinique\">frissons</span> ; <span class=\"kw-clinique\">foyer de râles crépitants</span> ; <span class=\"kw-clinique\">expectoration</span> purulente</li><li><span class=\"kw-radio\">Opacités alvéolaires souvent systématisées</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Syndrome inflammatoire</span>, <span class=\"kw-bio\">hyperleucocytose</span>, <span class=\"kw-bio\">PCT élevée</span> ; <span class=\"kw-bio\">antigénurie Légionelle / Pneumocoque</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> urgente ; surveiller l'<span class=\"kw-clinique\">évolution</span> possible vers un <span class=\"kw-etio\">SDRA</span> (<span class=\"kw-bio\">PaO2</span>/FiO2 &lt; 300)</li></ul>"},{"id":"t-oap","kind":"terminal","label":"OAP cardiogénique → VNI précoce","color":"red","detail":"<h4>Orientation</h4><ul><li>ATCD d'<span class=\"kw-etio\">insuffisance cardiaque</span> / FdRCV ; <span class=\"kw-clinique\">orthopnée</span>, <span class=\"kw-clinique\">expectoration</span> mousseuse rosée</li><li><span class=\"kw-clinique\">Crépitants bilatéraux</span> prédominant aux bases, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-clinique\">tachycardie</span> ; <span class=\"kw-radio\">opacités alvéolaires bilatérales péri-hilaires</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-bio\">BNP / NT-proBNP élevé</span> ; <span class=\"kw-imagerie\">ECG</span> et <span class=\"kw-imagerie\">échographie cardiaque</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">VNI</span> précoce (toutes formes : ↓ pré-charge et post-charge VG) ; séances de <span class=\"kw-chiffre\">1 h toutes les 3 h</span></li></ul>"},{"id":"t-pno","kind":"terminal","label":"Pneumothorax sous tension → geste de décompression","color":"red","detail":"<h4>Orientation</h4><ul><li>Début <span class=\"kw-clinique\">brutal</span> ; sujet longiligne, tabac / cannabis ; <span class=\"kw-clinique\">abolition du murmure vésiculaire et des vibrations vocales</span>, <span class=\"kw-clinique\">tympanisme</span> à la percussion</li></ul><h4>Signe radiologique</h4><ul><li><span class=\"kw-radio\">Hyperclarté délimitée par une ligne pleurale</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Pneumothorax sous tension</span> = <span class=\"kw-alerte\">urgence</span> vitale (<span class=\"kw-clinique\">cœur pulmonaire aigu</span>) → orientation immédiate pour geste spécialisé</li></ul>"},{"id":"q-capnie","kind":"decision","label":"Hypercapnie chronique ? (PaCO2 ≥ 45 + HCO3⁻ > 30)","branches":[{"to":"t-decomp","label":"Oui : hypercapnie + bicarbonates élevés","color":"amber"},{"to":"q-novo","label":"Non : pas de rétention chronique","color":"blue"}]},{"id":"t-decomp","kind":"terminal","label":"Décompensation d'une IRC → VNI si BPCO + acidose","color":"amber","detail":"<h4>Orientation</h4><ul><li><span class=\"kw-radio\">RXT normale ou subnormale</span> ; <span class=\"kw-bio\">hypercapnie (PaCO2 ≥ 45 mmHg) avec pH normal</span> ; <span class=\"kw-bio\">HCO3⁻ &gt; 30 mmol/L</span> (rétention chronique)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">VNI</span> si exacerbation de <span class=\"kw-etio\">BPCO</span> avec acidose respiratoire (<span class=\"kw-bio\">pH</span> &lt; 7,35) ; cible <span class=\"kw-chiffre\">SpO2 88-92%</span> ; traiter le facteur déclenchant</li></ul>"},{"id":"q-novo","kind":"decision","label":"Pathologie aiguë « de novo » — orientation clinique ?","branches":[{"to":"t-ep","label":"FdR thromboembolique ; TJ/RHJ ; RXT normale","color":"blue"},{"to":"t-aag","label":"Asthme connu ; freinage ; sibilants","color":"red"},{"to":"t-choc","label":"Hypotension ; marbrures ; effet basse PvO2","color":"red"}]},{"id":"t-ep","kind":"terminal","label":"Embolie pulmonaire → confirmer par TDM thoracique","color":"blue","detail":"<h4>Orientation</h4><ul><li><span class=\"kw-clinique\">FdR de maladie thromboembolique veineuse</span> ; douleur latéro-thoracique majorée à l'inspiration ; <span class=\"kw-clinique\">TJ / RHJ</span> (cœur pulmonaire aigu) ; auscultation normale</li><li><span class=\"kw-radio\">RXT normale ++</span> (parfois ascension de coupole, atélectasie en bande)</li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-bio\">GDS</span> : effet espace mort ; confirmation par <span class=\"kw-imagerie\">TDM thoracique</span></li></ul>"},{"id":"t-aag","kind":"terminal","label":"Asthme aigu grave → urgence + oxygénothérapie","color":"red","detail":"<h4>Orientation</h4><ul><li><span class=\"kw-etio\">Asthme connu</span> ; perte de contrôle / exacerbation préalable ; <span class=\"kw-clinique\">freinage expiratoire</span> ; <span class=\"kw-clinique\">sibilants ou silence auscultatoire</span></li><li><span class=\"kw-radio\">Distension thoracique</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Asthme aigu grave</span> = <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-clinique\">pouls paradoxal</span>, cœur pulmonaire aigu) ; <span class=\"kw-ttt\">oxygénothérapie</span> + orientation <span class=\"kw-alerte\">réanimation</span></li></ul>"},{"id":"t-choc","kind":"terminal","label":"État de choc → correction du choc","color":"red","detail":"<h4>Orientation</h4><ul><li><span class=\"kw-clinique\">Hypotension</span>, marbrures, signes d'hypoperfusion ; effet « <span class=\"kw-def\">basse PvO2</span> » (extraction périphérique d'O2 ↑ → aggrave l'hypoxémie en cas de shunt)</li></ul><h4>Conduite</h4><ul><li>La <span class=\"kw-ttt\">correction du choc</span> améliore l'oxygénation</li></ul><h4>Renvoi</h4><ul><li>Item 332 (États de <span class=\"kw-alerte\">choc</span>)</li></ul>"}]},"cards":[{"i":"7f9e98549ec3","n":359,"o":"359-1","u":"Définition","t":"Connaître la définition de la détresse et de l’insuffisance respiratoire aiguë","q":"Comment définit-on l'insuffisance respiratoire aiguë (IRA) ?","a":"<p>L'insuffisance respiratoire aiguë (IRA) est une <strong>définition gazométrique</strong> caractérisée par une altération aiguë de l'hématose. On distingue deux types :</p><ul><li><strong>IRA de type 1 (hypoxémique)</strong> : <strong>PaO2 &lt; 60 mmHg</strong>, sans hypercapnie.</li><li><strong>IRA de type 2 (hypercapnique)</strong> : <strong>PaCO2 &gt; 45 mmHg</strong>, pouvant rapidement se compliquer d'une acidose respiratoire.</li></ul>"},{"i":"9f34b2b22b2b","n":359,"o":"359-1","u":"Définition","t":"Connaître la définition de la détresse et de l’insuffisance respiratoire aiguë","q":"Quelle est la définition de la détresse respiratoire aiguë (DRA) ?","a":"<p>La détresse respiratoire aiguë (DRA) est une <strong>définition clinique</strong> qui correspond à un ensemble de signes respiratoires témoignant de la gravité d'une affection pulmonaire, traduisant l'inadéquation entre les charges imposées et les capacités de l'appareil respiratoire. Elle peut annoncer un arrêt cardio-respiratoire par hypoxie et regroupe les conséquences directes de l'atteinte (ex: <strong>cyanose</strong>) et les mécanismes compensateurs (recrutement des <strong>muscles respiratoires accessoires</strong>).</p>"},{"i":"e655ebce5c35","n":359,"o":"359-1","u":"Définition","t":"Connaître la définition de la détresse et de l’insuffisance respiratoire aiguë","q":"Quel est le lien entre détresse respiratoire aiguë (DRA) et insuffisance respiratoire aiguë (IRA) gazométrique ?","a":"<p>La détresse respiratoire aiguë (DRA) <strong>peut précéder</strong> une authentique insuffisance respiratoire aiguë (IRA) gazométrique. Une <strong>hypocapnie associée à une PaO2 normale</strong> peut témoigner d'une hypoxémie profonde masquée par l'hyperventilation alvéolaire, rendant les gaz du sang potentiellement faussement rassurants et nécessitant leur renouvellement précoce.</p>"},{"i":"fcade2d38ccb","n":359,"o":"359-1","u":"Définition","t":"Connaître la définition de la détresse et de l’insuffisance respiratoire aiguë","q":"L'hypoxie tissulaire sans hypoxémie est-elle incluse dans la définition de l'insuffisance respiratoire aiguë (IRA) ?","a":"<p>Non, l'hypoxie tissulaire sans hypoxémie <strong>n'entre PAS</strong> dans la définition de l'insuffisance respiratoire aiguë (IRA). Elle correspond à une altération du transport de l'O2 (comme dans l'<strong>anémie</strong>, l'<strong>intoxication au CO</strong>, l'<strong>état de choc</strong>) ou de la respiration cellulaire (comme dans l'<strong>intoxication au cyanure</strong> ou le <strong>sepsis grave</strong>).</p>"},{"i":"20c6536c45f3","n":359,"o":"359-13","u":"Contenu multimédia","t":"Savoir reconnaître un OAP sur une radiographie du thorax","q":"Quelle est la particularité de la répartition des opacités alvéolaires en cas d'OAP cardiogénique sur une radiographie du thorax ?","a":"<p>Les opacités alvéolaires en cas d'OAP cardiogénique ont une répartition :</p><ul><li><strong>bilatérale et symétrique</strong>.</li><li><strong>péri-hilaire</strong>, classiquement décrite comme « <strong>en ailes de papillon</strong> ».</p></ul>"},{"i":"5e2fd1c5768a","n":359,"o":"359-13","u":"Contenu multimédia","t":"Savoir reconnaître un OAP sur une radiographie du thorax","q":"Quels sont les signes radiologiques évocateurs d'un œdème aigu pulmonaire (OAP) cardiogénique sur une radiographie du thorax ?","a":"<p>Sur une radiographie thoracique, l'OAP cardiogénique se traduit par :</p><ul><li>Des <strong>opacités alvéolaires</strong>.</li><li>Ces opacités sont <strong>bilatérales</strong> et <strong>diffuses</strong>.</li><li>Elles ont une <strong>prédominance péri-hilaire</strong>, souvent décrites comme des « <strong>ailes de papillon</strong> ».</li><li>On peut également retrouver une <strong>redistribution vasculaire vers les sommets</strong>.</li><li>Et la présence de <strong>lignes de Kerley</strong>.</li></ul>"},{"i":"cf6df2656c31","n":359,"o":"359-13","u":"Contenu multimédia","t":"Savoir reconnaître un OAP sur une radiographie du thorax","q":"Quel est le contexte clinique qui doit faire évoquer un œdème aigu pulmonaire (OAP) radiologique cardiogénique ?","a":"<p>Le contexte clinique accompagnant un OAP radiologique cardiogénique inclut :</p><ul><li>Une <strong>orthopnée</strong>.</li><li>Des <strong>crépitants bilatéraux des bases</strong> à l'auscultation pulmonaire.</li><li>Une <strong>élévation du BNP / NT-proBNP</strong>.</li><li>Des <strong>antécédents d'insuffisance cardiaque</strong> ou de <strong>facteurs de risque cardio-vasculaires</strong>.</li></ul>"},{"i":"a1af021b33a8","n":359,"o":"359-14","u":"Contenu multimédia","t":"Savoir reconnaître une pneumonie sur une radiographie du thorax","q":"Quel est un signe radiologique spécifique de pneumonie alvéolaire en radiographie thoracique mentionné dans le contexte clinicoradiologique classique ?","a":"<p>Un signe radiologique spécifique de pneumonie alvéolaire est la présence d'un <strong>bronchogramme aérique</strong> au sein des opacités.</p>"},{"i":"d139ecccf567","n":359,"o":"359-14","u":"Contenu multimédia","t":"Savoir reconnaître une pneumonie sur une radiographie du thorax","q":"Comment se manifeste radiographiquement une pneumonie infectieuse sur une radiographie du thorax ?","a":"<p>Sur une radiographie thoracique, la pneumonie infectieuse se traduit par des <strong>opacités alvéolaires</strong>, volontiers <strong>systématisées</strong> (un lobe, un segment), de topographie généralement <strong>unique</strong>, et aux <strong>bords flous</strong>.</p>"},{"i":"fec594ff03d7","n":359,"o":"359-14","u":"Contenu multimédia","t":"Savoir reconnaître une pneumonie sur une radiographie du thorax","q":"Comment différencier radiographiquement une pneumonie d'un OAP (œdème aigu du poumon) sur une radiographie du thorax ?","a":"<p>Pour différencier radiographiquement une pneumonie d'un OAP :</p><ul><li>La <strong>pneumonie</strong> présente des opacités alvéolaires souvent <strong>systématisées, uniques</strong> et à bords flous.</li><li>L'<strong>OAP</strong> se manifeste par des <strong>opacités bilatérales, diffuses, péri-hilaires</strong>, et sans systématisation nette.</li></ul>"},{"i":"0923b8f8f9d7","n":359,"o":"359-15","u":"Étiologies","t":"Connaître les étiologies à l’origine de la détresse respiratoire aiguë du nourrisson et de l’enfant","q":"Quelles sont les étiologies infectieuses prédominantes des détresses respiratoires aiguës chez le nourrisson et l'enfant ?","a":"<p>Chez le nourrisson et l'enfant, les étiologies les plus fréquentes des détresses respiratoires aiguës sont les <strong>infections des voies aériennes</strong> et les <strong>crises d'asthme</strong>.</p>"},{"i":"29528d47738a","n":359,"o":"359-15","u":"Étiologies","t":"Connaître les étiologies à l’origine de la détresse respiratoire aiguë du nourrisson et de l’enfant","q":"Quelles sont les étiologies de détresse respiratoire aiguë \"sine materia\" (auscultation normale) chez l'enfant ?","a":"<ul><li><strong>Métaboliques</strong> : acidocétose diabétique, hyperthermie.</li><li><strong>Hémodynamiques</strong> : état de choc, anémie.</li><li><strong>Neurologiques</strong> : causes neuro-méningées.</li><li><strong>Psychologiques</strong> : causes psychogènes.</li></ul>"},{"i":"70224a4ec4d7","n":359,"o":"359-15","u":"Étiologies","t":"Connaître les étiologies à l’origine de la détresse respiratoire aiguë du nourrisson et de l’enfant","q":"Quelles sont les causes de détresse respiratoire aiguë non bruyante chez l'enfant ?","a":"<ul><li><strong>Causes pulmonaires</strong> : pneumopathie, pleurésie, pneumothorax.</li><li><strong>Causes cardiaques</strong> : myocardite, insuffisance cardiaque, OAP.</li></ul>"},{"i":"93e418732350","n":359,"o":"359-15","u":"Étiologies","t":"Connaître les étiologies à l’origine de la détresse respiratoire aiguë du nourrisson et de l’enfant","q":"Quelles sont les causes principales d'insuffisance cardiaque aiguë chez le nourrisson suspectée devant une détresse respiratoire ?","a":"<p>Chez le nourrisson, il faut évoquer des <strong>shunts gauche-droit</strong> (communication interventriculaire - CIV, canal atrio-ventriculaire - CAV, persistance du canal artériel - PCA), des <strong>myocardites infectieuses</strong> ou des <strong>troubles du rythme</strong> (tachycardies supraventriculaires).</p>"},{"i":"b7d9586e3f38","n":359,"o":"359-15","u":"Étiologies","t":"Connaître les étiologies à l’origine de la détresse respiratoire aiguë du nourrisson et de l’enfant","q":"Quelles sont les principales étiologies de dyspnée bruyante selon la localisation du bruit chez l'enfant ?","a":"<ul><li><strong>Dyspnée bruyante laryngée (inspiratoire)</strong> : rhinopharyngite obstructive, laryngomalacie, amygdalite/abcès rétro-pharyngé, laryngite sous-glottique.</li><li><strong>Dyspnée bruyante laryngée urgente</strong> : épiglottite, corps étranger laryngé, œdème laryngé sur anaphylaxie, coqueluche.</li><li><strong>Dyspnée bruyante trachéale</strong> : compression trachéale extrinsèque, corps étranger trachéal, sténose trachéale.</li><li><strong>Dyspnée bruyante bronchique (expiratoire)</strong> : corps étranger bronchique, bronchiolite, asthme.</li></ul>"},{"i":"d7cf25b2e42e","n":359,"o":"359-15","u":"Étiologies","t":"Connaître les étiologies à l’origine de la détresse respiratoire aiguë du nourrisson et de l’enfant","q":"Quelle étiologie doit être évoquée en priorité devant une dyspnée d'installation brutale après 6 mois chez l'enfant ?","a":"<p>Toute dyspnée d'installation brutale après 6 mois doit faire évoquer une <strong>inhalation de corps étranger</strong>. La recherche de signes d'insuffisance cardiaque aiguë doit être systématique.</p>"},{"i":"3b4402ce5d7b","n":359,"o":"359-16","u":"Étiologies","t":"Savoir reconnaître les causes les plus fréquentes chez l’adulte","q":"Quels sont les éléments cliniques et paracliniques typiques d'une décompensation aiguë de BPCO, à considérer en cas de détresse respiratoire aiguë ?","a":"<p>La décompensation aiguë de BPCO se caractérise par une <strong>hypercapnie</strong> avec un <strong>pH sanguin normal</strong> et des <strong>bicarbonates élevés</strong>, traduisant une acidose respiratoire chronique compensée.</p>"},{"i":"668e05ede951","n":359,"o":"359-16","u":"Étiologies","t":"Savoir reconnaître les causes les plus fréquentes chez l’adulte","q":"Quelles sont les causes fréquentes de détresse respiratoire aiguë chez l'adulte associées à des anomalies radiologiques ?","a":"<ul><li>La <strong>pneumonie infectieuse</strong> : fièvre, foyer de crépitants, opacité systématisée à la radiographie thoracique.</li><li>L'<strong>œdème aigu du poumon (OAP) cardiogénique</strong> : orthopnée, crépitants bilatéraux, augmentation du BNP.</li><li>Le <strong>pneumothorax sous tension</strong> : urgence vitale.</li></ul>"},{"i":"d4b49239e0e9","n":359,"o":"359-16","u":"Étiologies","t":"Savoir reconnaître les causes les plus fréquentes chez l’adulte","q":"Quelles sont les causes fréquentes de détresse respiratoire aiguë chez l'adulte pour lesquelles la radiographie thoracique peut être initialement normale ?","a":"<ul><li>L'<strong>embolie pulmonaire</strong> : associée à des facteurs de risque thrombo-emboliques, auscultation pulmonaire souvent normale.</li><li>Le <strong>pneumothorax simple</strong> : sujet jeune et longiligne, abolition du murmure vésiculaire à l'auscultation.</li><li>L'<strong>asthme aigu grave</strong> : sibilants ou silence auscultatoire.</li></ul>"},{"i":"fb8b490343e8","n":359,"o":"359-16","u":"Étiologies","t":"Savoir reconnaître les causes les plus fréquentes chez l’adulte","q":"Quelle est l'aide diagnostic essentielle pour orienter l'étiologie d'une détresse respiratoire aiguë chez l'adulte ?","a":"<p>La <strong>radiographie thoracique</strong> est l'examen clé permettant d'orienter le diagnostic étiologique d'une détresse respiratoire aiguë chez l'adulte.</p>"},{"i":"075f7f157df4","n":359,"o":"359-17","u":"Identifier une urgence","t":"Connaître les premiers gestes chez l’enfant présentant une détresse respiratoire d’origine ORL","q":"Quelle est la conduite à tenir en cas d'obstruction des voies aériennes supérieures par un corps étranger chez un enfant qui devient inconscient ?","a":"<p>En cas d'obstruction par un corps étranger et d'inconscience, il faut :</p><ul><li><strong>Libérer les voies aériennes</strong>.</li><li>Procéder à <strong>5 insufflations</strong>.</li><li>Démarrer la <strong>Réanimation Cardio-Pulmonaire (RCP)</strong> immédiatement.</li></ul>"},{"i":"a8503286d465","n":359,"o":"359-17","u":"Identifier une urgence","t":"Connaître les premiers gestes chez l’enfant présentant une détresse respiratoire d’origine ORL","q":"Quels sont les premiers gestes à réaliser, quel que soit le diagnostic, face à une détresse respiratoire aiguë d'origine ORL chez l'enfant ?","a":"<p>Les premiers gestes comprennent :</p><ul><li>La <strong>libération des voies aériennes supérieures</strong> (retrait d'un corps étranger visible, aspiration, désobstruction rhinopharyngée).</li><li>La <strong>mise en position adéquate</strong> : <strong>proclive</strong> chez le nourrisson, <strong>semi-assise</strong> chez l'enfant (ne jamais allonger).</li><li>L'<strong>oxygénothérapie</strong> adaptée à la SpO2.</li><li>La pose d'une <strong>VVP</strong> (voie veineuse périphérique) si retentissement hémodynamique.</li><li>Le <strong>transfert médicalisé</strong> (SAMU) et éventuellement vers une unité de soins intensifs (USI).</li></ul>"},{"i":"f8a228fb7610","n":359,"o":"359-17","u":"Identifier une urgence","t":"Connaître les premiers gestes chez l’enfant présentant une détresse respiratoire d’origine ORL","q":"Comment doit-on prendre en charge un œdème de Quincke obstructif entraînant une détresse respiratoire aiguë chez l'enfant ?","a":"<p>En cas d'œdème de Quincke obstructif, il faut administrer de l'<strong>adrénaline en injection intramusculaire (IM)</strong> à la dose de <strong>0,5 mg</strong> immédiatement. Il s'agit d'une urgence vitale.</p>"},{"i":"fd0046c5101c","n":359,"o":"359-17","u":"Identifier une urgence","t":"Connaître les premiers gestes chez l’enfant présentant une détresse respiratoire d’origine ORL","q":"Quelle est la conduite à tenir face à une obstruction des VAS par un corps étranger chez un enfant conscient dont la toux est inefficace ?","a":"<p>Il faut réaliser les <strong>manœuvres d'expulsion</strong> spécifiques :</p><ul><li>Pour un nourrisson : <strong>5 tapes dorsales</strong> suivies de <strong>5 compressions thoraciques</strong> (manœuvre de Mofenson). La manœuvre de Heimlich est contre-indiquée.</li><li>Pour un enfant : <strong>5 tapes dorsales</strong> suivies de <strong>5 compressions abdominales</strong> (manœuvre de Heimlich).</li></ul>"},{"i":"1d593a11c603","n":359,"o":"359-18","u":"Identifier une urgence","t":"Connaître les premiers gestes chez l’adulte présentant une inhalation de corps étranger","q":"Quelle est la conduite à tenir immédiate face à une inhalation de corps étranger chez un adulte lorsque l'obstacle est complet et que le patient est conscient ?","a":"<p>Face à une inhalation de corps étranger avec <strong>obstacle complet</strong> (toux inefficace, cyanose, risque d'arrêt cardiaque) chez un patient conscient, la conduite à tenir est la <strong>manœuvre de Heimlich</strong>. Elle consiste en des pressions abdominales brutales de bas en haut, exercées au creux épigastrique pour créer une hyperpression intra-thoracique.</p>"},{"i":"c8acae1f1a20","n":359,"o":"359-18","u":"Identifier une urgence","t":"Connaître les premiers gestes chez l’adulte présentant une inhalation de corps étranger","q":"Quelle est l'attitude thérapeutique en cas d'inhalation de corps étranger avec obstacle incomplet chez l'adulte ?","a":"<p>En cas d'inhalation de corps étranger avec <strong>obstacle incomplet</strong> chez l'adulte (ventilation spontanée possible avec stridor, cornage, wheezing), il faut :</p><ul><li><strong>Éviter toute mobilisation</strong> et respecter la position spontanément choisie par le patient.</li><li><strong>Proscrire les manœuvres d'expulsion</strong> (risque de mobiliser le corps étranger).</li><li>Respecter la <strong>toux efficace</strong>.</li><li>Placer le patient en <strong>position demi-assise</strong>.</li><li>Administrer de l'<strong>oxygénothérapie</strong>.</li><li>Orientation vers un <strong>plateau technique</strong> pour fibroscopie.</li><li>Appeler les secours (<strong>SAMU</strong>), arrêter l'ingestion d'aliments et boissons, et mettre en place un <strong>monitoring</strong>.</li></ul>"},{"i":"df11d947c897","n":359,"o":"359-18","u":"Identifier une urgence","t":"Connaître les premiers gestes chez l’adulte présentant une inhalation de corps étranger","q":"Comment prendre en charge une inhalation de corps étranger chez un adulte lorsque l'obstacle est complet et que le patient est inconscient ?","a":"<p>Lorsque l'obstacle est complet chez un patient <strong>inconscient</strong> suite à une inhalation de corps étranger, il faut l'allonger, rechercher un corps étranger pharyngé volumineux et débuter la <strong>réanimation cardio-pulmonaire (RCP)</strong>. La RCP est plus efficace pour expulser un corps étranger sur un plan dur.</p>"},{"i":"0fdd6dce904e","n":359,"o":"359-19","u":"Prise en charge","t":"Connaître les modalités d’oxygénation initiale","q":"À partir de quel débit d'oxygène le recours à un réanimateur est-il impératif ?","a":"<p>Un besoin d'oxygène <strong>supérieur à 5 L/min</strong> impose de contacter un réanimateur.</p>"},{"i":"70243f284213","n":359,"o":"359-19","u":"Prise en charge","t":"Connaître les modalités d’oxygénation initiale","q":"Dans quelle situation la Ventilation Non Invasive (VNI) est-elle la modalité d'oxygénation de première intention en cas d'insuffisance respiratoire aiguë ?","a":"<p>La VNI est indiquée en première intention en cas d'<strong>insuffisance respiratoire aiguë hypercapnique</strong> (IRA hypercapnique), ainsi que pour l'<strong>OAP cardiogénique</strong> et l'<strong>exacerbation de BPCO avec acidose</strong>.</p>"},{"i":"aa2abc9b173f","n":359,"o":"359-19","u":"Prise en charge","t":"Connaître les modalités d’oxygénation initiale","q":"Quelle est la particularité de l'oxygénothérapie chez le patient BPCO en détresse respiratoire aiguë ?","a":"<ul><li>L'oxygénothérapie n'est <strong>pas toxique</strong> chez le BPCO.</li><li>Il n'existe <strong>pas de débit minimal</strong>.</li><li>La cible de saturation est adaptée à <strong>88-92 %</strong>.</li><li>Il ne faut <strong>jamais sous-doser l'O2</strong> par peur de l'hypercapnie, car l'hypoxémie tue immédiatement.</li></ul>"},{"i":"d31458e10f8d","n":359,"o":"359-19","u":"Prise en charge","t":"Connaître les modalités d’oxygénation initiale","q":"Quand faut-il réaliser un gaz du sang de contrôle lors d'une oxygénothérapie pour détresse respiratoire aiguë ?","a":"<p>Un gaz du sang de contrôle doit être réalisé lorsque la SpO2 est stabilisée entre <strong>92-96 %</strong> pour évaluer le risque, inconstant, d'hypercapnie par inhibition des centres respiratoires.</p>"},{"i":"d3d71f7fa397","n":359,"o":"359-19","u":"Prise en charge","t":"Connaître les modalités d’oxygénation initiale","q":"Quels sont l'objectif de saturation en oxygène (SpO2) et la modalité d'oxygénothérapie initiale en cas d'insuffisance respiratoire aiguë (IRA) hypoxémique ?","a":"<p>L'objectif de SpO2 est <strong>> 90 %</strong>. En cas d'IRA hypoxémique, l'oxygénothérapie initiale se fait par un <strong>masque à haute concentration (MHC)</strong> à un débit de <strong>12-15 L/min</strong>.</p>"},{"i":"ea3d092bd0d2","n":359,"o":"359-19","u":"Prise en charge","t":"Connaître les modalités d’oxygénation initiale","q":"Quelle est la première chose à éliminer devant une détresse respiratoire aiguë avant l'oxygénation ?","a":"<p>Le premier réflexe est d'éliminer la présence d'un <strong>corps étranger dans les voies aériennes supérieures (VAS)</strong>.</p>"},{"i":"081b8572f889","n":359,"o":"359-2","u":"Définition","t":"Connaître les critères de diagnostic, les variations avec l’âge","q":"Comment le diagnostic de détresse respiratoire aiguë est-il posé ?","a":"<p>Le diagnostic de détresse respiratoire aiguë est <strong>exclusivement clinique</strong>, posé dès l'<strong>inspection</strong> du patient. Un <strong>seul signe</strong> respiratoire suffit pour établir ce diagnostic.</p>"},{"i":"7d4a309fd467","n":359,"o":"359-2","u":"Définition","t":"Connaître les critères de diagnostic, les variations avec l’âge","q":"Quelles sont les définitions de la tachypnée et de la polypnée chez l'adulte en contexte de détresse respiratoire aiguë ?","a":"<ul><li>La <strong>tachypnée</strong> est définie par une fréquence respiratoire (FR) <strong>≥ 25/min</strong>.</li><li>La <strong>polypnée</strong> ou tachypnée est définie par une FR <strong>> 16/min</strong>.</li><li>La <strong>polypnée superficielle</strong> associe une accélération de la FR et une diminution du volume courant.</li></ul>"},{"i":"cec67a496c70","n":359,"o":"359-2","u":"Définition","t":"Connaître les critères de diagnostic, les variations avec l’âge","q":"Comment interpréter les signes respiratoires en cas de suspicion de détresse respiratoire aiguë ?","a":"<p>L'interprétation des signes respiratoires, et notamment des fréquences respiratoire et cardiaque, doit toujours tenir compte de l'<strong>âge</strong> du patient. Ces paramètres varient fortement chez l'enfant et peuvent également être influencés par la <strong>fièvre</strong>, l'<strong>agitation</strong> ou l'<strong>anxiété</strong>.</p>"},{"i":"068844455fa7","n":359,"o":"359-21","u":"Identifier une urgence","t":"Savoir orienter en urgence un patient en détresse respiratoire aiguë pour un geste spécialisé","q":"Quels sont les critères justifiant un appel au réanimateur pour une détresse respiratoire aiguë ?","a":"<ul><li>Un besoin en O2 <strong>supérieur à 5 L/min</strong>.</li><li>Toute <strong>détresse respiratoire persistante</strong> ou <strong>non isolée</strong> (associée à d'autres défaillances).</li></ul>"},{"i":"199858e9bd77","n":359,"o":"359-21","u":"Identifier une urgence","t":"Savoir orienter en urgence un patient en détresse respiratoire aiguë pour un geste spécialisé","q":"Dans quel contexte la bronchoscopie rigide est-elle la technique de choix pour l'extraction d'un corps étranger bronchique ?","a":"<p>La bronchoscopie rigide est la technique de choix :</p><ul><li>Après <strong>échec d'une bronchoscopie souple</strong>.</li><li>D'emblée si le diagnostic est <strong>quasi-certain</strong>, notamment en présence d'une <strong>diminution unilatérale du murmure vésiculaire</strong> et un <strong>piégeage ipsilatéral sur la radiographie thoracique</strong>.</li></ul><p>Elle nécessite une <strong>anesthésie générale</strong> chez l'enfant.</p>"},{"i":"199d7434ec34","n":359,"o":"359-21","u":"Identifier une urgence","t":"Savoir orienter en urgence un patient en détresse respiratoire aiguë pour un geste spécialisé","q":"Quand la bronchoscopie souple est-elle indiquée pour l'extraction d'un corps étranger bronchique ?","a":"<p>La bronchoscopie souple est indiquée :</p><ul><li>Chez l'adulte si le corps étranger n'est <strong>pas trop volumineux</strong>.</li><li>D'emblée si la probabilité d'un corps étranger <strong>récent est faible</strong>, car elle est moins invasive.</li></ul>"},{"i":"808a2684a6ca","n":359,"o":"359-21","u":"Identifier une urgence","t":"Savoir orienter en urgence un patient en détresse respiratoire aiguë pour un geste spécialisé","q":"Quelle est la conduite à tenir face à la suspicion d'une inhalation de corps étranger nécessitant un geste spécialisé, et par qui doit-elle être réalisée ?","a":"<p>L'extraction d'un corps étranger bronchique doit être réalisée en <strong>centre spécialisé</strong> par des <strong>pédiatres, pneumologues ou ORL</strong>. Une tentative d'extraction par du personnel non formé n'est pas recommandée.</p>"},{"i":"cd4fb92f96b9","n":359,"o":"359-21","u":"Identifier une urgence","t":"Savoir orienter en urgence un patient en détresse respiratoire aiguë pour un geste spécialisé","q":"Comment orienter initialement un patient présentant une détresse respiratoire aiguë, selon l'objectif EDN ?","a":"<p>Tout patient en détresse respiratoire aiguë doit être conduit vers un <strong>centre disposant du plateau technique adapté</strong> pour une prise en charge spécialisée.</p>"},{"i":"bd6ea06db353","n":359,"o":"359-6","u":"Identifier une urgence","t":"Reconnaître les signes de gravité cliniques et gazométriques","q":"Comment interpréter la gazométrie artérielle en cas de détresse respiratoire aiguë ?","a":"<p>En cas de détresse respiratoire aiguë (DRA) :</p><ul><li>La DRA s'accompagne le plus souvent d'une <strong>hypocapnie</strong> (hyperventilation alvéolaire réflexe à l'hypoxémie).</li><li>L'<strong>acidose respiratoire secondaire à l'hypercapnie</strong> est un signe de gravité supplémentaire.</li><li>Une <strong>normocapnie</strong> est <strong>anormale</strong> dans une détresse respiratoire et a la même valeur de gravité qu'une hypercapnie. C'est un piège majeur.</li><li>L'hypercapnie ne se voit que dans deux situations : décompensation d'insuffisance respiratoire chronique et épuisement respiratoire.</li></ul>"},{"i":"c543959b60d8","n":359,"o":"359-6","u":"Identifier une urgence","t":"Reconnaître les signes de gravité cliniques et gazométriques","q":"Quels sont les signes cliniques de faillite respiratoire, traduisant une décompensation de détresse respiratoire aiguë ?","a":"<p>Les signes de faillite respiratoire sont :</p><ul><li>La <strong>respiration abdominale paradoxale</strong>, témoignant d'une faillite de la pompe ventilatoire et s'accompagnant souvent d'une orthopnée (le décubitus dorsal étant alors contre-indiqué).</li><li>La <strong>cyanose</strong>, visible lorsque l'hémoglobine désoxygénée est <strong>supérieure à 5 g/dL</strong>, et témoignant d'une hypoxémie profonde (<strong>SaO2 ≤ 85 %</strong>). Elle peut être absente ou tardive en cas d'anémie profonde. Regarder la couleur de la langue chez les mélanodermes. Elle impose une oxygénothérapie immédiate.</li><li>Un <strong>retentissement neurologique</strong> : astérixis (flapping, très évocateur d'hypercapnie), troubles du comportement ou de la vigilance (liés à l'hypercapnie et/ou l'hypoxie cérébrale). Un score de Glasgow <strong>≤ 8</strong> impose l'intubation.</li></ul>"},{"i":"e4911d98aeb0","n":359,"o":"359-6","u":"Identifier une urgence","t":"Reconnaître les signes de gravité cliniques et gazométriques","q":"Quels sont les signes de gravité circulatoires et les signes d'hypercapnie extra-neurologiques à rechercher systématiquement en cas de détresse respiratoire aiguë ?","a":"<p>Les signes de gravité circulatoires sont :</p><ul><li>Le <strong>cœur pulmonaire aigu</strong> : turgescence jugulaire, reflux hépato-jugulaire, hépatomégalie douloureuse, signe de Harzer.</li><li>Le <strong>pouls paradoxal</strong> : diminution de la PAS à l'inspiration de <strong>&gt; 10 mmHg</strong>.</li><li>La recherche d'un <strong>état de choc</strong> (retentissement hémodynamique).</li></ul><p>Les signes d'hypercapnie extra-neurologiques sont :</p><ul><li>Réponse adrénergique : sueurs, tremblements, tachycardie, HTA.</li><li>Effet vasodilatateur du CO2 : céphalées, hypervascularisation des conjonctives.</li></ul>"},{"i":"e7a20671f8b8","n":359,"o":"359-6","u":"Identifier une urgence","t":"Reconnaître les signes de gravité cliniques et gazométriques","q":"Quels sont les signes cliniques de lutte respiratoire chez l'adulte, en cas de détresse respiratoire aiguë ?","a":"<p>Les signes de lutte respiratoire, qui traduisent une compensation, sont :</p><ul><li>Une <strong>tachypnée</strong> (fréquence respiratoire <strong>≥ 25/min</strong> chez l'adulte), parfois une polypnée superficielle.</li><li>Des signes de réduction du volume courant : <strong>hypophonie</strong> (difficulté à parler) et inefficacité de la toux.</li><li>Des <strong>tirages</strong> (recrutement des muscles accessoires).</li><li>Une expiration abdominale active (suggère une obstruction).</li><li>Un battement des ailes du nez (surtout chez le très jeune enfant).</li></ul>"},{"i":"66af6765c4a8","n":359,"o":"359-7","u":"Identifier une urgence","t":"Savoir reconnaître les signes de détresse respiratoires suite à l’inhalation d’un corps étranger chez l’enfant et chez l’adulte, ou en cas d’épiglottite de l’enfant et de l’adulte","q":"Qu'est-ce que le syndrome de pénétration en cas d'inhalation de corps étranger ?","a":"<p>Il s'agit d'un tableau clinique survenant <strong>brutalement</strong> chez un individu précédemment sain, souvent lors d'un repas ou d'un jeu, et témoignant de l'inhalation d'un corps étranger. Il se manifeste initialement par une <strong>toux quinteuse</strong>, parfois un tirage inspiratoire et un accès de suffocation.</p>"},{"i":"7b1a7e57ec72","n":359,"o":"359-7","u":"Identifier une urgence","t":"Savoir reconnaître les signes de détresse respiratoires suite à l’inhalation d’un corps étranger chez l’enfant et chez l’adulte, ou en cas d’épiglottite de l’enfant et de l’adulte","q":"Quels sont les signes évocateurs d'un corps étranger de localisation laryngée ?","a":"<ul><li><strong>Dyspnée inspiratoire</strong>.</li><li><strong>Stridor</strong> (aigu) ou <strong>cornage</strong> (rauque, sous-glottique).</li><li><strong>Toux permanente</strong>.</li></ul>"},{"i":"8487a6a94ec3","n":359,"o":"359-7","u":"Identifier une urgence","t":"Savoir reconnaître les signes de détresse respiratoires suite à l’inhalation d’un corps étranger chez l’enfant et chez l’adulte, ou en cas d’épiglottite de l’enfant et de l’adulte","q":"Quels sont les signes cliniques généraux de l'inhalation d'un corps étranger chez l'enfant ou l'adulte ?","a":"<ul><li><strong>Agitation</strong> et panique du patient.</li><li>Gestes évoquant l'étranglement (mains au cou).</li><li><strong>Toux quinteuse</strong>.</li><li><strong>Tirage inspiratoire</strong> et <strong>cornage</strong>, pouvant mener à la cyanose et au malaise.</li><li><strong>Dysphonie</strong>, voire aphonie si obstruction complète.</li><li><strong>Bradypnée inspiratoire</strong>.</li></ul>"},{"i":"ad05d1e4ffeb","n":359,"o":"359-7","u":"Identifier une urgence","t":"Savoir reconnaître les signes de détresse respiratoires suite à l’inhalation d’un corps étranger chez l’enfant et chez l’adulte, ou en cas d’épiglottite de l’enfant et de l’adulte","q":"Quels sont les signes évocateurs d'un corps étranger de localisation bronchique ?","a":"<ul><li><strong>Dyspnée expiratoire</strong>.</li><li><strong>Wheezing</strong>.</li><li><strong>Râles sibilants ou sous-crépitants unilatéraux</strong>.</li></ul>"},{"i":"daa6042938e2","n":359,"o":"359-7","u":"Identifier une urgence","t":"Savoir reconnaître les signes de détresse respiratoires suite à l’inhalation d’un corps étranger chez l’enfant et chez l’adulte, ou en cas d’épiglottite de l’enfant et de l’adulte","q":"Comment différencier une détresse respiratoire due à une épiglottite d'une inhalation de corps étranger chez l'enfant ou l'adulte ?","a":"<p>Bien que les deux puissent présenter un tirage et un cornage, l'<strong>épiglottite</strong> se caractérise par des éléments distinctifs :</p><ul><li>Une <strong>fièvre élevée</strong>.</li><li>Une <strong>voix étouffée</strong>.</li><li>Une <strong>hypersalivation</strong>.</li><li>Une <strong>toux absente</strong>.</li><li>Une bouche demi-ouverte.</li><li>Une <strong>majoration de la dyspnée en position couchée</strong> (décubitus).</li></ul>"},{"i":"3ad9e07203b3","n":359,"o":"359-8","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","q":"Quels sont les éléments anamnestiques et cliniques évocateurs d'une embolie pulmonaire (EP) aiguë en cause d'une insuffisance respiratoire aiguë chez l'adulte ?","a":"<p>Devant une insuffisance respiratoire aiguë, une embolie pulmonaire est évoquée si :</p><ul><li>Antécédents : <strong>facteurs de risque de maladie thrombo-embolique</strong>.</li><li>Début : <strong>rapide voire brutal</strong>.</li><li>Signes fonctionnels : <strong>douleur latéro-thoracique</strong> majorée à l'inspiration, toux non productive, hémoptysie (rare).</li><li>Examen clinique : auscultation normale, parfois <strong>turgescence jugulaire</strong> (signe d'insuffisance ventriculaire droite).</li></ul>"},{"i":"70da5804edb6","n":359,"o":"359-8","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","q":"Quels sont les éléments anamnestiques et cliniques évocateurs d'une pneumonie infectieuse en cause d'une insuffisance respiratoire aiguë chez l'adulte ?","a":"<p>Devant une insuffisance respiratoire aiguë, une pneumonie infectieuse est évoquée si :</p><ul><li>Antécédents : parfois <strong>immunodépression</strong>.</li><li>Signes généraux : <strong>fièvre élevée</strong>, frissons.</li><li>Signes fonctionnels : <strong>expectoration purulente</strong>, douleur rythmée par la respiration.</li><li>Examen clinique : <strong>foyer de râles crépitants</strong>.</li></ul>"},{"i":"7578041b38f1","n":359,"o":"359-8","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","q":"Quels sont les éléments anamnestiques et cliniques évocateurs d'un œdème aigu du poumon (OAP) cardiogénique en cause d'une insuffisance respiratoire aiguë chez l'adulte ?","a":"<p>Devant une insuffisance respiratoire aiguë, un œdème aigu du poumon cardiogénique est évoqué si :</p><ul><li>Antécédents : <strong>insuffisance cardiaque</strong>, facteurs de risque cardio-vasculaires.</li><li>Signes généraux : aucun.</li><li>Signes fonctionnels : <strong>expectoration mousseuse</strong> parfois rosée, <strong>orthopnée</strong>.</li><li>Examen clinique : <strong>crépitants bilatéraux des bases</strong>, tachycardie, hypertension artérielle.</li></ul>"},{"i":"944b04af9d0b","n":359,"o":"359-8","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","q":"Quelles sont les étiologies à évoquer devant une dyspnée \"sine materia\" (auscultation pulmonaire normale) en cause d'une insuffisance respiratoire aiguë chez l'enfant ?","a":"<p>Une dyspnée \"sine materia\" chez l'enfant (dyspnée avec auscultation normale) peut orienter vers des causes non respiratoires primaires comme :</p><ul><li>Une <strong>acidocétose diabétique</strong>.</li><li>Une <strong>anémie</strong>.</li><li>Un <strong>état de choc</strong>.</li><li>Une <strong>hyperthermie</strong>.</li><li>Des causes <strong>psychogènes</strong>.</li></ul>"},{"i":"9ef5cc2e7906","n":359,"o":"359-8","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","q":"Quels sont les éléments anamnestiques et cliniques évocateurs d'un pneumothorax aigu en cause d'une insuffisance respiratoire aiguë chez l'adulte ?","a":"<p>Devant une insuffisance respiratoire aiguë, un pneumothorax est évoqué si :</p><ul><li>Antécédents : <strong>sujet longiligne</strong>, <strong>tabac/cannabis</strong>, pathologie respiratoire \"à risque\".</li><li>Début : <strong>brutal</strong>, parfois après un effort.</li><li>Signes fonctionnels : <strong>douleur latéro-thoracique</strong>, toux non productive.</li><li>Examen clinique : <strong>abolition du murmure vésiculaire</strong>, <strong>tympanisme</strong> à la percussion.</li></ul>"},{"i":"a666e1639bde","n":359,"o":"359-8","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","q":"Comment orienter l'étiologie d'une insuffisance respiratoire aiguë chez l'enfant en fonction du type de dyspnée bruyante ?","a":"<p>Chez l'enfant, une dyspnée bruyante oriente vers une <strong>obstruction des voies aériennes</strong> :</p><ul><li><strong>Laryngée</strong> : stridor, tirage.</li><li><strong>Trachéale</strong>.</li><li><strong>Bronchique</strong> : sibilants, freinage expiratoire.</li></ul>"},{"i":"c31550edc970","n":359,"o":"359-8","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","q":"Comment orienter l'étiologie d'une insuffisance respiratoire aiguë chez l'enfant en présence d'une dyspnée non bruyante avec auscultation anormale ?","a":"<p>Chez l'enfant, une dyspnée non bruyante avec auscultation anormale peut orienter vers :</p><ul><li>Une <strong>pneumopathie</strong>.</li><li>Une <strong>pleurésie</strong>.</li><li>Un <strong>pneumothorax</strong>.</li><li>Une <strong>bronchiolite</strong>.</li><li>Une <strong>myocardite/OAP</strong>.</li></ul>"},{"i":"e80166e2d16d","n":359,"o":"359-8","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l’adulte et l’enfant","q":"Quels sont les éléments anamnestiques et cliniques évocateurs d'un asthme aigu grave en cause d'une insuffisance respiratoire aiguë chez l'adulte ?","a":"<p>Devant une insuffisance respiratoire aiguë, un asthme aigu grave est évoqué si :</p><ul><li>Antécédents : <strong>asthme connu</strong>.</li><li>Début : <strong>perte de contrôle</strong> de l'asthme ou exacerbation.</li><li>Signes fonctionnels : <strong>freinage expiratoire</strong>.</li><li>Examen clinique : <strong>sibilants</strong> diffus ou, signe de gravité extrême, <strong>silence auscultatoire</strong>.</li></ul>"},{"i":"01a2b204c716","n":359,"o":"359-9","u":"Examens complémentaires","t":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","q":"Quel est le piège diagnostique à connaître concernant l'évolution d'une pneumonie infectieuse dans le cadre d'une détresse respiratoire aiguë ?","a":"<p>Une <strong>pneumonie infectieuse</strong> peut évoluer vers un <strong>Syndrome de Détresse Respiratoire Aiguë (SDRA)</strong>. Il faut y penser devant une <strong>aggravation</strong> de l'état clinique du patient.</p>"},{"i":"102edb69f409","n":359,"o":"359-9","u":"Examens complémentaires","t":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","q":"Face à une détresse respiratoire aiguë, quelles étiologies fréquentes doivent être recherchées prioritairement si la radiographie thoracique ne présente pas d'anomalies ?","a":"<p>Si la radiographie thoracique ne présente pas d'anomalies, les étiologies à rechercher prioritairement sont :</p><ul><li><strong>Pathologies aiguës « de novo »</strong> : <ul><li><strong>Embolie pulmonaire (EP)</strong></li><li><strong>Pneumothorax</strong></li><li><strong>Asthme aigu grave</strong></li><li><strong>État de choc</strong></li></ul></li><li><strong>Décompensation d'une pathologie respiratoire chronique</strong></li></ul>"},{"i":"5d25fb6d6fe5","n":359,"o":"359-9","u":"Examens complémentaires","t":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","q":"Face à une détresse respiratoire aiguë, quelles étiologies fréquentes doivent être recherchées en priorité si la radiographie thoracique présente des anomalies ?","a":"<p>Si la radiographie thoracique montre des anomalies, les étiologies à rechercher en priorité incluent :</p><ul><li><strong>Pneumonie infectieuse</strong></li><li><strong>Œdème aigu pulmonaire (OAP)</strong></li><li><strong>Pneumothorax sous tension</strong></li><li><strong>SDRA (Syndrome de Détresse Respiratoire Aiguë)</strong></li><li><strong>Exacerbation de pneumopathie interstitielle diffuse (PID)</strong></li></ul>"},{"i":"6b39ae3e63fc","n":359,"o":"359-9","u":"Examens complémentaires","t":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","q":"Comment la gazométrie artérielle, notamment la PaCO2 et le pH sanguin, peut-elle orienter vers une décompensation de pathologie respiratoire chronique face à une détresse respiratoire aiguë ?","a":"<p>Une <strong>décompensation d'une pathologie respiratoire chronique</strong> est évoquée devant :</p><ul><li>Une <strong>hypercapnie (PaCO2 ≥ 45 mmHg) à pH normal</strong></li><li>Une <strong>élévation des bicarbonates (HCO3⁻ > 30 mmol/L)</strong>, ce qui signe une hypercapnie chronique compensée.</li></ul>"},{"i":"94b6897efa47","n":359,"o":"359-9","u":"Examens complémentaires","t":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","q":"Quelle est la première étape obligatoire à réaliser en urgence face à une détresse ou insuffisance respiratoire aiguë, et quand doit-elle être faite ?","a":"<p>La première étape obligatoire face à une détresse respiratoire aiguë est d'<strong>éliminer une obstruction des voies aériennes supérieures</strong>. Cette évaluation doit être réalisée <strong>après la prise en charge symptomatique initiale</strong> (oxygénothérapie ± ventilation mécanique), et jamais avant.</p>"},{"i":"a4d7888c644b","n":359,"o":"359-9","u":"Examens complémentaires","t":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","q":"Quelles sont les définitions gazométriques de l'hypoxémie pouvant orienter le diagnostic d'une détresse respiratoire aiguë ?","a":"<p>L'hypoxémie est définie par :</p><ul><li>Une <strong>PaO2 &lt; 80 mmHg en air ambiant</strong></li><li>Ou un <strong>rapport PaO2/FiO2 &lt; 300</strong></li></ul>"},{"i":"d08104520729","n":359,"o":"359-9","u":"Examens complémentaires","t":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","q":"Quels examens complémentaires sont indiqués selon le contexte pour affiner le diagnostic étiologique d'une détresse respiratoire aiguë, notamment en cas de suspicion d'OAP, d'EP ou d'obstruction des VAS ?","a":"<p>Selon le contexte, les examens complémentaires spécifiques incluent :</p><ul><li><strong>Échographie transthoracique (ETT)</strong> en cas de suspicion d'<strong>OAP</strong></li><li><strong>TDM thoracique</strong> (scanner) en cas de suspicion d'<strong>Embolie Pulmonaire (EP)</strong> ou de <strong>pneumopathie interstitielle diffuse (PID)</strong></li><li><strong>Scanner cervical</strong> en cas de suspicion d'<strong>obstruction des voies aériennes supérieures (VAS)</strong></li></ul>"},{"i":"f82d961c26ea","n":359,"o":"359-9","u":"Examens complémentaires","t":"Connaître la stratégie d’investigations à visée étiologique pour les hypothèses fréquentes (décompensation de broncho-pneumopathie chronique obstructive (BPCO), œdème aigu pulmonaire (OAP), embolie pulmonaire (EP), pneumopathie (PNP), asthme, bronchiolites, pathologies des voies aériennes supérieures)","q":"Quels sont les examens complémentaires de base à réaliser systématiquement lors du bilan étiologique d'une détresse respiratoire aiguë ?","a":"<ul><li><strong>Radiographie thoracique</strong></li><li><strong>Gaz du sang</strong></li><li><strong>Lactates</strong></li><li><strong>ECG</strong> (Électrocardiogramme)</li></ul>"}]};